part of harvest_place_app;

class HpjCommunityScreen extends StatefulWidget {
  final void Function(Product product) onAddProduct;
  final void Function(Product product) onOpenProduct;
  final bool embeddedInNavigation;

  const HpjCommunityScreen({
    super.key,
    required this.onAddProduct,
    required this.onOpenProduct,
    this.embeddedInNavigation = false,
  });

  @override
  State<HpjCommunityScreen> createState() => _HpjCommunityScreenState();
}

class _HpjCommunityScreenState extends State<HpjCommunityScreen> {
  late Future<List<Product>> _productsFuture;
  late Future<List<FarmPublicProfileRecord>> _farmsFuture;
  Set<String> followedFarmIds = <String>{};

  @override
  void initState() {
    super.initState();
    _productsFuture = fetchProductsForCustomerUi(
      timeout: const Duration(seconds: 8),
    );
    _farmsFuture = fetchPublishedFarmPublicProfiles(limit: 40);
    unawaited(_loadFollowed());
  }

  Future<void> _loadFollowed() async {
    final ids = await fetchCurrentUserFollowedFarmIds();
    if (!mounted) return;
    setState(() => followedFarmIds = ids);
  }

  Future<void> _refresh() async {
    final products = fetchProductsForCustomerUi(
      forceRefresh: true,
      timeout: const Duration(seconds: 8),
    );
    final farms = fetchPublishedFarmPublicProfiles(limit: 40);

    if (mounted) {
      setState(() {
        _productsFuture = products;
        _farmsFuture = farms;
      });
    }

    await Future.wait<dynamic>([
      products,
      farms,
      _loadFollowed(),
    ]);
  }

  Future<void> _openFarm(FarmPublicProfileRecord farm) async {
    await Navigator.of(context).push<void>(
      MaterialPageRoute<void>(
        builder: (_) => PublicFarmProfileScreen(
          farmerId: farm.farmerId,
          sourceWorkspace: 'customer',
          onAddProduct: widget.onAddProduct,
        ),
      ),
    );
    if (!mounted) return;
    await _loadFollowed();
  }

  void _openReels() {
    Navigator.of(context).push<void>(
      MaterialPageRoute<void>(
        builder: (_) => HpjFreshReelsEntryScreen(
          onAddToCart: widget.onAddProduct,
        ),
      ),
    );
  }

  void _openMealComposer() {
    Navigator.of(context).push<void>(
      MaterialPageRoute<void>(
        builder: (_) => const HpjMealPulseScreen(
          openComposerOnStart: true,
        ),
      ),
    );
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      backgroundColor: const Color(0xFFF7F8F3),
      appBar: AppBar(
        automaticallyImplyLeading: !widget.embeddedInNavigation,
        backgroundColor: Colors.white,
        surfaceTintColor: Colors.white,
        elevation: 0,
        leading: widget.embeddedInNavigation
            ? const Padding(
                padding: EdgeInsets.only(left: 12),
                child: Icon(
                  Icons.groups_2_rounded,
                  color: FarmColors.deepGreen,
                  size: 24,
                ),
              )
            : null,
        titleSpacing: widget.embeddedInNavigation ? 8 : 16,
        title: const Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            Text(
              'Community',
              style: TextStyle(
                color: FarmColors.deepGreen,
                fontSize: 20,
                height: 1,
                fontWeight: FontWeight.w900,
                letterSpacing: -.35,
              ),
            ),
            SizedBox(height: 3),
            Text(
              'Real people. Real meals. Real farms. A stronger Jamaica.',
              maxLines: 1,
              overflow: TextOverflow.ellipsis,
              style: TextStyle(
                color: FarmColors.mutedText,
                fontSize: 8.5,
                fontWeight: FontWeight.w700,
              ),
            ),
          ],
        ),
        actions: [
          IconButton(
            tooltip: 'Post to Community',
            onPressed: _openMealComposer,
            icon: const Icon(Icons.add_circle_outline_rounded),
          ),
          const SizedBox(width: 4),
        ],
      ),
      body: RefreshIndicator(
        onRefresh: _refresh,
        child: FutureBuilder<List<Product>>(
          future: _productsFuture,
          builder: (context, productSnapshot) {
            final products =
                productSnapshot.data ?? const <Product>[];

            return FutureBuilder<List<FarmPublicProfileRecord>>(
              future: _farmsFuture,
              builder: (context, farmSnapshot) {
                final farms = farmSnapshot.data ??
                    const <FarmPublicProfileRecord>[];

                if ((productSnapshot.connectionState ==
                            ConnectionState.waiting ||
                        farmSnapshot.connectionState ==
                            ConnectionState.waiting) &&
                    products.isEmpty &&
                    farms.isEmpty) {
                  return ListView(
                    physics: const AlwaysScrollableScrollPhysics(),
                    children: const [
                      SizedBox(
                        height: 360,
                        child: Center(
                          child: CircularProgressIndicator(),
                        ),
                      ),
                    ],
                  );
                }

                return ListView(
                  physics: const AlwaysScrollableScrollPhysics(),
                  padding: const EdgeInsets.fromLTRB(12, 10, 12, 120),
                  children: [
                    _HpjCommunityHomeFeed(
                      farms: farms,
                      products: products,
                      followedFarmIds: followedFarmIds,
                      onOpenFarm: _openFarm,
                      onOpenReels: _openReels,
                      onOpenProduct: widget.onOpenProduct,
                      onAddProduct: widget.onAddProduct,
                      maxCards: 10,
                      fullScreen: true,
                    ),
                  ],
                );
              },
            );
          },
        ),
      ),
    );
  }
}

