class _HpjSocialFeedTabs extends StatelessWidget {
  final String selected;
  final ValueChanged<String> onSelected;

  const _HpjSocialFeedTabs({
    required this.selected,
    required this.onSelected,
  });

  @override
  Widget build(BuildContext context) {
    const tabs = <String>[
      'For You',
      'Following',
      'Near You',
      'Trending',
    ];

    return Row(
      children: tabs
          .map(
            (tab) => Padding(
              padding: const EdgeInsets.only(right: 6),
              child: ChoiceChip(
                label: Text(tab),
                selected: selected == tab,
                onSelected: (_) => onSelected(tab),
                showCheckmark: false,
                selectedColor: FarmColors.primary,
                backgroundColor: const Color(0xFFF7F8F4),
                side: BorderSide(
                  color: selected == tab
                      ? FarmColors.primary
                      : HpjWebUi.border,
                ),
                labelStyle: TextStyle(
                  color: selected == tab
                      ? Colors.white
                      : FarmColors.ink,
                  fontSize: 8.9,
                  fontWeight: FontWeight.w900,
                ),
                padding: const EdgeInsets.symmetric(
                  horizontal: 12,
                  vertical: 6,
                ),
              ),
            ),
          )
          .toList(),
    );
  }
}

class _HpjFeaturedFarmSocialCard extends StatelessWidget {
  final List<FarmPublicProfileRecord> farms;
  final List<Product> products;
  final String feedMode;
  final Set<String> followedFarmIds;
  final void Function(String farmerId, bool isFollowing)
      onFollowChanged;
  final VoidCallback onOpenReels;
  final Future<void> Function(FarmPublicProfileRecord farm) onOpenFarm;
  final VoidCallback onDiscoverFarms;
  final void Function(Product product) onAddProduct;

  const _HpjFeaturedFarmSocialCard({
    required this.farms,
    required this.products,
    required this.feedMode,
    required this.followedFarmIds,
    required this.onFollowChanged,
    required this.onOpenReels,
    required this.onOpenFarm,
    required this.onDiscoverFarms,
    required this.onAddProduct,
  });

  FarmPublicProfileRecord? _pickFarm() {
    if (farms.isEmpty) return null;

    switch (feedMode) {
      case 'Near You':
        return farms.length > 2 ? farms[2] : farms.first;
      case 'Trending':
        return farms.length > 3 ? farms[3] : farms.first;
      case 'Following':
      case 'For You':
      default:
        return farms.first;
    }
  }

  @override
  Widget build(BuildContext context) {
    final farm = _pickFarm();

    if (feedMode == 'Following' && farm == null) {
      return Container(
        height: 254,
        padding: const EdgeInsets.all(24),
        decoration: BoxDecoration(
          color: Colors.white,
          borderRadius: BorderRadius.circular(16),
          border: Border.all(color: HpjWebUi.border),
        ),
        child: Row(
          children: [
            Container(
              width: 72,
              height: 72,
              alignment: Alignment.center,
              decoration: BoxDecoration(
                color: FarmColors.primarySoft,
                borderRadius: BorderRadius.circular(22),
              ),
              child: const Icon(
                Icons.notifications_none_rounded,
                color: FarmColors.primary,
                size: 34,
              ),
            ),
            const SizedBox(width: 18),
            const Expanded(
              child: Column(
                mainAxisAlignment: MainAxisAlignment.center,
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  Text(
                    'Build your Following feed',
                    style: TextStyle(
                      color: FarmColors.deepGreen,
                      fontSize: 22,
                      fontWeight: FontWeight.w900,
                    ),
                  ),
                  SizedBox(height: 7),
                  Text(
                    'Follow Jamaican farms to see their harvests, Fresh Reels and marketplace updates here.',
                    style: TextStyle(
                      color: FarmColors.mutedText,
                      fontSize: 11,
                      height: 1.35,
                      fontWeight: FontWeight.w600,
                    ),
                  ),
                ],
              ),
            ),
            const SizedBox(width: 18),
            FilledButton.icon(
              onPressed: onDiscoverFarms,
              icon: const Icon(Icons.travel_explore_rounded),
              label: const Text('Discover Farms'),
            ),
          ],
        ),
      );
    }

    final farmProducts = farm == null
        ? products.take(2).toList()
        : products
            .where(
              (product) =>
                  product.farmerId?.trim() ==
                  farm.farmerId.trim(),
            )
            .take(2)
            .toList();

    final fallbackProduct =
        farmProducts.isNotEmpty ? farmProducts.first : null;

    final cover = cleanHostedImageUrl(farm?.coverImageUrl);
    final farmName = farm?.publicName.trim().isNotEmpty == true
        ? farm!.publicName.trim()
        : (fallbackProduct?.farmName ??
                fallbackProduct?.farmerName ??
                'HPJ Jamaican Farm')
            .trim();

    final location = farm?.locationLine ?? 'Jamaica';

    return Container(
      height: 254,
      clipBehavior: Clip.antiAlias,
      decoration: BoxDecoration(
        color: FarmColors.deepGreen,
        borderRadius: BorderRadius.circular(16),
        border: Border.all(color: HpjWebUi.border),
      ),
      child: Stack(
        fit: StackFit.expand,
        children: [
          if (cover != null)
            Image.network(
              cover,
              fit: BoxFit.cover,
              errorBuilder: (_, __, ___) =>
                  const ColoredBox(
                color: FarmColors.deepGreen,
              ),
            )
          else if (fallbackProduct != null)
            Container(
              color: const Color(0xFFEAF2E7),
              alignment: Alignment.center,
              child: ProductVisual(
                product: fallbackProduct,
                size: 360,
                showOrganicBadge: false,
              ),
            )
          else
            const DecoratedBox(
              decoration: BoxDecoration(
                gradient: LinearGradient(
                  begin: Alignment.topLeft,
                  end: Alignment.bottomRight,
                  colors: [
                    Color(0xFF0A422E),
                    Color(0xFF2D7747),
                  ],
                ),
              ),
            ),
          DecoratedBox(
            decoration: BoxDecoration(
              gradient: LinearGradient(
                begin: Alignment.centerLeft,
                end: Alignment.centerRight,
                colors: [
                  const Color(0xFF061E16).withOpacity(0.88),
                  const Color(0xFF0B3828).withOpacity(0.60),
                  Colors.transparent,
                  const Color(0xFF061E16).withOpacity(0.22),
                ],
                stops: const [0.0, 0.42, 0.70, 1.0],
              ),
            ),
          ),
          Positioned(
            left: 18,
            top: 14,
            right: 18,
            child: Row(
              children: [
                CircleAvatar(
                  radius: 18,
                  backgroundColor: Colors.white,
                  backgroundImage:
                      cleanHostedImageUrl(farm?.logoImageUrl) == null
                          ? null
                          : NetworkImage(
                              cleanHostedImageUrl(
                                farm?.logoImageUrl,
                              )!,
                            ),
                  child:
                      cleanHostedImageUrl(farm?.logoImageUrl) == null
                          ? const Icon(
                              Icons.eco_outlined,
                              color: FarmColors.primary,
                            )
                          : null,
                ),
                const SizedBox(width: 9),
                Expanded(
                  child: Column(
                    crossAxisAlignment:
                        CrossAxisAlignment.start,
                    children: [
                      Row(
                        children: [
                          Flexible(
                            child: Text(
                              farmName,
                              maxLines: 1,
                              overflow: TextOverflow.ellipsis,
                              style: const TextStyle(
                                color: Colors.white,
                                fontSize: 12.5,
                                fontWeight: FontWeight.w900,
                              ),
                            ),
                          ),
                          if (farm?.hpjVerified == true) ...[
                            const SizedBox(width: 5),
                            const Icon(
                              Icons.verified_rounded,
                              color: Color(0xFFF1C44D),
                              size: 15,
                            ),
                          ],
                        ],
                      ),
                      const SizedBox(height: 2),
                      Text(
                        location,
                        maxLines: 1,
                        overflow: TextOverflow.ellipsis,
                        style: TextStyle(
                          color: Colors.white.withOpacity(0.84),
                          fontSize: 8.8,
                          fontWeight: FontWeight.w600,
                        ),
                      ),
                    ],
                  ),
                ),
                if (farm != null) ...[
                  FarmFollowButton(
                    farmerId: farm.farmerId,
                    compact: true,
                    onDark: true,
                    onChanged: (value) {
                      onFollowChanged(
                        farm.farmerId,
                        value,
                      );
                    },
