}

class _HpjFreshPickProductCard extends StatelessWidget {
  final Product product;
  final bool favorite;
  final VoidCallback onFavorite;
  final VoidCallback onOpen;
  final VoidCallback onAdd;

  const _HpjFreshPickProductCard({
    required this.product,
    required this.favorite,
    required this.onFavorite,
    required this.onOpen,
    required this.onAdd,
  });

  String get _sourceName {
    final farm = (product.farmName ?? '').trim();
    if (farm.isNotEmpty) return farm;

    final farmer = (product.farmerName ?? '').trim();
    if (farmer.isNotEmpty) return farmer;

    return 'HPJ Marketplace';
  }

  List<Widget> _badges() {
    final badges = <Widget>[];

    if (product.hasActiveDiscount) {
      badges.add(
        const _HpjFreshPickBadge(
          label: 'DEAL',
          background: Color(0xFFF6C526),
          foreground: FarmColors.deepGreen,
        ),
      );
    }

    if (product.isOrganic && badges.length < 2) {
      badges.add(
        const _HpjFreshPickBadge(
          label: 'ORGANIC',
          background: FarmColors.primary,
          foreground: Colors.white,
        ),
      );
    }

    if (isProductHarvestedThisWeek(product) && badges.length < 2) {
      badges.add(
        const _HpjFreshPickBadge(
          label: 'FRESH',
          background: Color(0xFFE7F3E3),
          foreground: FarmColors.primary,
        ),
      );
    }

    return badges.take(2).toList();
  }

  @override
  Widget build(BuildContext context) {
    final unit = (product.unit ?? '').trim();
    final badges = _badges();

    return Material(
      color: const Color(0xFFFEFFFD),
      borderRadius: BorderRadius.circular(12),
      child: InkWell(
        onTap: onOpen,
        borderRadius: BorderRadius.circular(12),
        child: Container(
          padding: const EdgeInsets.all(8),
          decoration: BoxDecoration(
            borderRadius: BorderRadius.circular(12),
            border: Border.all(color: HpjWebUi.border),
          ),
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              Expanded(
                child: Stack(
                  children: [
                    Positioned.fill(
                      child: Container(
                        decoration: BoxDecoration(
                          color: const Color(0xFFF5F8F2),
                          borderRadius: BorderRadius.circular(10),
                        ),
                        alignment: Alignment.center,
                        child: ProductVisual(
                          product: product,
                          size: 112,
                          showOrganicBadge: false,
                        ),
                      ),
                    ),
                    if (badges.isNotEmpty)
                      Positioned(
                        left: 5,
                        top: 5,
                        child: Wrap(
                          spacing: 4,
                          children: badges,
                        ),
                      ),
                    Positioned(
                      right: 3,
                      top: 3,
                      child: IconButton(
                        onPressed: onFavorite,
                        padding: EdgeInsets.zero,
                        constraints: const BoxConstraints(
                          minWidth: 28,
                          minHeight: 28,
                        ),
                        style: IconButton.styleFrom(
                          backgroundColor:
                              Colors.white.withOpacity(0.92),
                        ),
                        icon: Icon(
                          favorite
                              ? Icons.favorite_rounded
                              : Icons.favorite_border_rounded,
                          color: favorite
                              ? FarmColors.danger
                              : FarmColors.deepGreen,
                          size: 17,
                        ),
                      ),
                    ),
                  ],
                ),
              ),
              const SizedBox(height: 6),
              Text(
                product.name,
                maxLines: 1,
                overflow: TextOverflow.ellipsis,
                style: const TextStyle(
                  color: FarmColors.ink,
                  fontSize: 9.4,
                  fontWeight: FontWeight.w900,
                ),
              ),
              const SizedBox(height: 2),
              Text(
                _sourceName,
                maxLines: 1,
                overflow: TextOverflow.ellipsis,
                style: const TextStyle(
                  color: FarmColors.mutedText,
                  fontSize: 7.4,
                  fontWeight: FontWeight.w600,
                ),
              ),
              const SizedBox(height: 3),
              Row(
                crossAxisAlignment: CrossAxisAlignment.end,
                children: [
                  Flexible(
                    child: Text(
                      'J\$${product.effectivePrice.toStringAsFixed(0)}'
                      '${unit.isEmpty ? '' : ' / $unit'}',
                      maxLines: 1,
                      overflow: TextOverflow.ellipsis,
                      style: const TextStyle(
                        color: FarmColors.deepGreen,
                        fontSize: 8.8,
                        fontWeight: FontWeight.w900,
                      ),
                    ),
                  ),
                  if (product.hasActiveDiscount &&
                      !product.isOutOfStock) ...[
                    const SizedBox(width: 5),
                    Flexible(
                      child: Text(
                        product.formattedOriginalPrice,
                        maxLines: 1,
                        overflow: TextOverflow.ellipsis,
                        style: const TextStyle(
                          color: FarmColors.mutedText,
                          fontSize: 7.1,
                          fontWeight: FontWeight.w600,
                          decoration: TextDecoration.lineThrough,
                        ),
                      ),
                    ),
                  ],
                ],
              ),
              const SizedBox(height: 6),
              SizedBox(
                width: double.infinity,
                height: 30,
                child: FilledButton.icon(
                  onPressed:
                      product.canAddToCart ? onAdd : null,
                  icon: const Icon(
                    Icons.shopping_cart_outlined,
                    size: 13,
                  ),
                  label: Text(
                    product.canAddToCart
                        ? 'Add to Box'
                        : 'Unavailable',
                  ),
                  style: FilledButton.styleFrom(
                    backgroundColor: FarmColors.primary,
                    foregroundColor: Colors.white,
                    padding: const EdgeInsets.symmetric(
                      horizontal: 6,
                    ),
                    textStyle: const TextStyle(
                      fontSize: 7.8,
                      fontWeight: FontWeight.w900,
                    ),
                    shape: RoundedRectangleBorder(
                      borderRadius: BorderRadius.circular(8),
                    ),
                  ),
                ),
              ),
            ],
          ),
        ),
      ),
    );
  }
}

