// ============================================================================
// HPJ PHASE 94W — PREMIUM CUSTOMER WEB SOCIAL HOME
// Desktop web only: community-first centre feed + live action cards on right rail.
// Mobile/app navigation and layouts remain unchanged.
// ============================================================================

class _HpjCommunityHomeFeed extends StatefulWidget {
  final List<FarmPublicProfileRecord> farms;
  final List<Product> products;
  final Set<String> followedFarmIds;
  final Future<void> Function(FarmPublicProfileRecord farm) onOpenFarm;
  final VoidCallback onOpenReels;
  final void Function(Product product) onOpenProduct;
  final void Function(Product product) onAddProduct;
  final int maxCards;
  final bool homePreview;
  final bool fullScreen;
  final VoidCallback? onOpenCommunity;

  const _HpjCommunityHomeFeed({
    required this.farms,
    required this.products,
    required this.followedFarmIds,
    required this.onOpenFarm,
    required this.onOpenReels,
    required this.onOpenProduct,
    required this.onAddProduct,
    this.maxCards = 3,
    this.homePreview = false,
    this.fullScreen = false,
    this.onOpenCommunity,
  });

  @override
  State<_HpjCommunityHomeFeed> createState() =>
      _HpjCommunityHomeFeedState();
}

class _HpjCommunityHomeFeedState extends State<_HpjCommunityHomeFeed> {
  String _filter = 'All';
  String _nearArea = 'St. Elizabeth';
  late Future<List<HpjMealPost>> _mealFuture;

  static const _filters = <String>[
    'All',
    'Near You',
    'Meals',
    'Farm Updates',
    'Produce',
  ];

  @override
  void initState() {
    super.initState();
    hpjCustomerParishPreference.addListener(
      _applySharedParishPreference,
    );
    _mealFuture = fetchHpjMealPulse(limit: 8);
    unawaited(_loadNearArea());
  }

  void _applySharedParishPreference() {
    final next = _hpjCanonicalCustomerParish(
      hpjCustomerParishPreference.value,
    );

    if (!mounted || next == _nearArea) return;
    setState(() => _nearArea = next);
  }

  Future<void> _loadNearArea() async {
    final saved = await HpjSmartLocalStore.readString('shop_near_area');
    final checkout = await HpjSmartLocalStore.readString('checkout_zone');
    final value = (saved ?? '').trim().isNotEmpty
        ? saved!.trim()
        : (checkout ?? '').trim().isNotEmpty
            ? checkout!.trim()
            : 'St. Elizabeth';
    if (!mounted) return;

    final canonical = _hpjCanonicalCustomerParish(value);
    setState(() => _nearArea = canonical);

    if (hpjCustomerParishPreference.value != canonical) {
      hpjCustomerParishPreference.value = canonical;
    }
  }

  @override
  void dispose() {
    hpjCustomerParishPreference.removeListener(
      _applySharedParishPreference,
    );
    super.dispose();
  }

  String _nearKey(String value) => value
      .trim().toLowerCase().replaceAll('saint ', 'st ')
      .replaceAll('.', '').replaceAll(RegExp(r'\s+'), ' ');

  bool _matchesNear(String value) {
    final area = _nearKey(_nearArea);
    final candidate = _nearKey(value);
    return area.isNotEmpty && candidate.contains(area);
  }

  bool _farmNear(FarmPublicProfileRecord farm) => _matchesNear(farm.locationLine);

  bool _productNear(Product product) {
    final direct = (product.parish ?? '').trim();
    if (_matchesNear(direct)) return true;
    final farmerId = (product.farmerId ?? '').trim();
    final farmName = (product.farmName ?? product.farmerName ?? '').trim().toLowerCase();
    for (final farm in widget.farms) {
      if ((farmerId.isNotEmpty && farm.farmerId.trim() == farmerId) ||
          (farmName.isNotEmpty && farm.publicName.trim().toLowerCase() == farmName)) {
        if (_farmNear(farm)) return true;
      }
    }
    return false;
  }

  Future<void> _openMealPulse({bool composer = false}) async {
    await Navigator.of(context).push<void>(
      MaterialPageRoute<void>(
        builder: (_) => HpjMealPulseScreen(
          openComposerOnStart: composer,
        ),
      ),
    );
    if (!mounted) return;
    setState(() {
      _mealFuture = fetchHpjMealPulse(limit: 8);
    });
  }

  List<Product> _visibleProducts() {
    final rows = widget.products
        .where((product) => !product.isOutOfStock)
        .toList();

    int score(Product product) {
      var value = 0;

      // Selected-parish produce gets the strongest recommendation boost.
      if (_productNear(product)) value += 1000;

      if (isProductHarvestedThisWeek(product)) value += 100;
      if (product.hasActiveDiscount) value += 80;
      if (product.isOrganic) value += 50;
      if (product.isLocal) value += 30;
      if (product.canAddToCart) value += 20;
      return value;
    }

    rows.sort((a, b) {
      final byScore = score(b).compareTo(score(a));
      if (byScore != 0) return byScore;
      return a.name.toLowerCase().compareTo(b.name.toLowerCase());
    });
    return rows;
  }

  Widget _buildPremiumHomePreview({
    required List<HpjMealPost> meals,
    required List<FarmPublicProfileRecord> farms,
    required List<Product> products,
  }) {
    final meal = meals.isNotEmpty ? meals.first : null;
    final farm = farms.isNotEmpty ? farms.first : null;
    final product = products.isNotEmpty ? products.first : null;

    Widget preview;

    if (meal != null) {
      preview = _HpjPremiumCommunityPreviewTile(
        imageUrl: meal.imageUrl,
        icon: Icons.restaurant_menu_rounded,
        eyebrow: 'MEAL PULSE',
        title: meal.mealName.trim().isEmpty ? 'Fresh from the community' : meal.mealName,
        subtitle: meal.displayName.trim().isEmpty
            ? 'Shared by an HPJ member'
            : '${meal.displayName} • ${_hpjMealRelativeTime(meal.createdAt)}',
        meta: '${meal.likeCount} likes • ${meal.commentCount} comments',
        onTap: () => _openMealPulse(),
      );
    } else if (farm != null) {
      preview = _HpjPremiumCommunityPreviewTile(
        imageUrl: cleanHostedImageUrl(farm.coverImageUrl) ??
            cleanHostedImageUrl(farm.logoImageUrl) ??
            '',
        icon: Icons.eco_outlined,
        eyebrow: 'FARM UPDATE',
        title: farm.publicName,
        subtitle: farm.locationLine,
        meta: widget.followedFarmIds.contains(farm.farmerId.trim())
            ? 'Following • View farm story'
            : 'Discover this Jamaican farm',
        onTap: () => widget.onOpenFarm(farm),
      );
    } else if (product != null) {
      preview = _HpjPremiumCommunityPreviewTile(
        product: product,
        icon: Icons.shopping_basket_outlined,
        eyebrow: 'FRESH PRODUCE',
        title: product.name,
        subtitle: (product.farmName ?? product.farmerName ?? 'Jamaican farm')
            .trim(),
        meta: product.canAddToCart ? 'Available now • Tap to shop' : 'Currently unavailable',
        onTap: () => widget.onOpenProduct(product),
      );
    } else {
      preview = Material(
        color: const Color(0xFFF7F9F5),
        borderRadius: BorderRadius.circular(17),
        child: InkWell(
          borderRadius: BorderRadius.circular(17),
          onTap: widget.onOpenCommunity,
          child: const Padding(
            padding: EdgeInsets.symmetric(horizontal: 14, vertical: 13),
            child: Text(
              'Community activity will appear here as meals, farm updates and fresh produce are shared.',
              style: TextStyle(
                color: FarmColors.mutedText,
                fontSize: 9.6,
                height: 1.35,
                fontWeight: FontWeight.w700,
              ),
            ),
          ),
        ),
      );
    }

    return Container(
      padding: const EdgeInsets.fromLTRB(12, 11, 12, 12),
      decoration: BoxDecoration(
        color: const Color(0xFFFFFEFB),
        borderRadius: BorderRadius.circular(21),
        border: Border.all(color: const Color(0xFFE1E7DF)),
      ),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Row(
            children: [
              const Expanded(
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    Text(
                      'From Our Community',
                      style: TextStyle(
                        color: FarmColors.deepGreen,
                        fontSize: 14.5,
                        height: 1,
                        fontWeight: FontWeight.w900,
                        letterSpacing: -.2,
                      ),
                    ),
                    SizedBox(height: 3),
                    Text(
                      'Meals, farms and fresh Jamaican produce.',
                      maxLines: 1,
                      overflow: TextOverflow.ellipsis,
                      style: TextStyle(
                        color: FarmColors.mutedText,
                        fontSize: 8.5,
                        fontWeight: FontWeight.w700,
                      ),
                    ),
                  ],
                ),
              ),
              TextButton(
                onPressed: widget.onOpenCommunity,
                style: TextButton.styleFrom(
                  visualDensity: VisualDensity.compact,
                  padding: const EdgeInsets.symmetric(horizontal: 7, vertical: 4),
                ),
                child: const Text('See All'),
              ),
            ],
          ),
          const SizedBox(height: 9),
          preview,
        ],
      ),
    );
  }

  @override
  Widget build(BuildContext context) {
    return FutureBuilder<List<HpjMealPost>>(
      future: _mealFuture,
      builder: (context, snapshot) {
        final allMeals = snapshot.data ?? const <HpjMealPost>[];
        final allFarms = _hpjPrioritizeFarmsByParish(
          widget.farms,
          _nearArea,
        );
        final allProducts = _visibleProducts();
        final nearMode = _filter == 'Near You';
        final meals = nearMode
            ? allMeals.where((meal) => _matchesNear(meal.parish)).toList()
            : allMeals;
        final farms = nearMode
            ? allFarms.where(_farmNear).toList()
            : allFarms;
        final products = nearMode
            ? allProducts.where(_productNear).toList()
            : allProducts;
        final cards = <Widget>[];

        if (widget.homePreview) {
          return _buildPremiumHomePreview(
            meals: meals,
            farms: farms,
            products: products,
          );
        }

        void addMeal(HpjMealPost post) {
          cards.add(
            _HpjCommunityMealCard(
              post: post,
              onTap: () => _openMealPulse(),
            ),
          );
        }

        void addFarm(FarmPublicProfileRecord farm) {
          cards.add(
            _HpjCommunityFarmCard(
              farm: farm,
              following: widget.followedFarmIds.contains(
                farm.farmerId.trim(),
              ),
              onTap: () => widget.onOpenFarm(farm),
            ),
          );
        }

        void addProduct(Product product) {
          cards.add(
            _HpjCommunityProduceCard(
              product: product,
              onOpen: () => widget.onOpenProduct(product),
              onAdd: () => widget.onAddProduct(product),
            ),
          );
        }

        if (_filter == 'Near You') {
          if (meals.isNotEmpty) addMeal(meals.first);
          if (farms.isNotEmpty) addFarm(farms.first);
          if (products.isNotEmpty) addProduct(products.first);
        } else if (_filter == 'Meals') {
          for (final meal in meals.take(widget.maxCards)) {
            addMeal(meal);
          }
        } else if (_filter == 'Farm Updates') {
          for (final farm in farms.take(widget.maxCards)) {
            addFarm(farm);
          }
        } else if (_filter == 'Produce') {
          for (final product in products.take(widget.maxCards)) {
            addProduct(product);
          }
        } else {
          if (meals.isNotEmpty) addMeal(meals.first);
          if (farms.isNotEmpty) addFarm(farms.first);
          if (products.isNotEmpty) addProduct(products.first);

          var mealIndex = 1;
          var farmIndex = 1;
          var productIndex = 1;
          while (cards.length < widget.maxCards) {
            if (mealIndex < meals.length) {
              addMeal(meals[mealIndex++]);
              continue;
            }
            if (farmIndex < farms.length) {
              addFarm(farms[farmIndex++]);
              continue;
            }
            if (productIndex < products.length) {
              addProduct(products[productIndex++]);
              continue;
            }
            break;
          }
        }

        return Container(
          width: double.infinity,
          padding: widget.fullScreen
              ? EdgeInsets.zero
              : const EdgeInsets.fromLTRB(14, 12, 14, 14),
          decoration: widget.fullScreen
              ? null
              : BoxDecoration(
                  color: Colors.white,
                  borderRadius: BorderRadius.circular(18),
                  border: Border.all(color: HpjWebUi.border),
                  boxShadow: [
                    BoxShadow(
                      color: FarmColors.deepGreen.withOpacity(.035),
                      blurRadius: 22,
                      offset: const Offset(0, 9),
                    ),
                  ],
                ),
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              if (!widget.fullScreen) ...[
              Row(
                children: [
                  Container(
                    width: 38,
                    height: 38,
                    decoration: BoxDecoration(
                      color: FarmColors.primarySoft,
                      borderRadius: BorderRadius.circular(12),
                    ),
                    child: const Icon(
                      Icons.groups_2_rounded,
                      color: FarmColors.primary,
                      size: 20,
                    ),
                  ),
                  const SizedBox(width: 10),
                  Expanded(
                    child: Column(
                      crossAxisAlignment: CrossAxisAlignment.start,
                      children: [
                        const Text(
                          'From Our Community',
                          style: TextStyle(
                            color: FarmColors.deepGreen,
                            fontSize: 17,
                            fontWeight: FontWeight.w900,
                            letterSpacing: -.25,
                          ),
                        ),
                        SizedBox(height: 2),
                        Text(
                          _filter == 'Near You'
                              ? 'Fresh community activity around $_nearArea.'
                              : 'Real meals. Real farms. Fresh produce. A stronger Jamaica.',
                          style: TextStyle(
                            color: FarmColors.mutedText,
                            fontSize: 9.2,
                            fontWeight: FontWeight.w600,
                          ),
                        ),
                      ],
                    ),
                  ),
                  const SizedBox(width: 10),
                  TextButton.icon(
                    onPressed: widget.homePreview && widget.onOpenCommunity != null
                        ? widget.onOpenCommunity
                        : widget.onOpenReels,
                    icon: Icon(
                      widget.homePreview
                          ? Icons.arrow_forward_rounded
                          : Icons.play_circle_outline_rounded,
                      size: 15,
                    ),
                    label: Text(
                      widget.homePreview ? 'See All' : 'Farm Reels',
                    ),
                  ),
                ],
              ),
              const SizedBox(height: 10),
              ],
              SingleChildScrollView(
                scrollDirection: Axis.horizontal,
                physics: const BouncingScrollPhysics(),
                child: Row(
                  children: _filters.map((filter) {
                    final selected = filter == _filter;
                    return Padding(
                      padding: const EdgeInsets.only(right: 7),
                      child: ChoiceChip(
                        label: Text(filter),
                        selected: selected,
                        onSelected: (_) {
                          if (!mounted) return;
                          setState(() => _filter = filter);
                        },
                        labelStyle: TextStyle(
                          color: selected ? Colors.white : FarmColors.deepGreen,
                          fontSize: 8.2,
                          fontWeight: FontWeight.w800,
                        ),
                        selectedColor: FarmColors.deepGreen,
                        backgroundColor: const Color(0xFFF4F8F1),
                        side: BorderSide(
                          color: selected
                              ? FarmColors.deepGreen
                              : const Color(0xFFE0E8DC),
                        ),
                        padding: const EdgeInsets.symmetric(
                          horizontal: 9,
                          vertical: 5,
                        ),
                        showCheckmark: false,
                      ),
                    );
                  }).toList(growable: false),
                ),
              ),
              const SizedBox(height: 11),
              if (snapshot.connectionState == ConnectionState.waiting &&
                  meals.isEmpty &&
                  _filter == 'Meals')
                const SizedBox(
                  height: 240,
                  child: Center(child: CircularProgressIndicator()),
                )
              else if (cards.isEmpty)
                _HpjCommunityEmptyCard(
                  filter: _filter == 'Near You' ? 'Near You • $_nearArea' : _filter,
                  onPostMeal: () => _openMealPulse(composer: true),
                )
              else
                LayoutBuilder(
                  builder: (context, constraints) {
                    final columns = constraints.maxWidth >= 720
                        ? 3
                        : constraints.maxWidth >= 470
                            ? 2
                            : 1;
                    final width = columns == 1
                        ? constraints.maxWidth
                        : (constraints.maxWidth - ((columns - 1) * 10)) /
                            columns;

                    return Wrap(
                      spacing: 10,
                      runSpacing: 10,
                      children: cards
                          .map(
                            (card) => SizedBox(
                              width: width,
                              child: card,
                            ),
                          )
                          .toList(),
                    );
                  },
                ),
              if (!widget.homePreview) ...[
                const SizedBox(height: 10),
                // Both actions were previously forced into a single Row. On a
                // narrow phone, their minimum widths exceeded the 337px feed.
                // Wrap keeps both actions available without a RenderFlex overflow.
                Wrap(
                  spacing: 8,
                  runSpacing: 4,
                  alignment: WrapAlignment.spaceBetween,
                  children: [
                    TextButton.icon(
                      onPressed: () => _openMealPulse(composer: true),
                      icon: const Icon(Icons.add_a_photo_outlined, size: 16),
                      label: const Text('Share today’s meal'),
                    ),
                    TextButton.icon(
                      onPressed: () => _openMealPulse(),
                      icon: const Icon(Icons.arrow_forward_rounded, size: 15),
                      iconAlignment: IconAlignment.end,
                      label: const Text('Open Meal Pulse'),
                    ),
                  ],
                ),
              ],
            ],
          ),
        );
      },
    );
  }
}

class _HpjPremiumCommunityPreviewTile extends StatelessWidget {
  final String imageUrl;
  final Product? product;
  final IconData icon;
  final String eyebrow;
  final String title;
  final String subtitle;
  final String meta;
  final VoidCallback? onTap;

  const _HpjPremiumCommunityPreviewTile({
    this.imageUrl = '',
    this.product,
    required this.icon,
    required this.eyebrow,
    required this.title,
    required this.subtitle,
    required this.meta,
    this.onTap,
  });

  @override
  Widget build(BuildContext context) {
    final clean = cleanHostedImageUrl(imageUrl);

    return Material(
      color: const Color(0xFFF7F9F5),
      borderRadius: BorderRadius.circular(17),
      clipBehavior: Clip.antiAlias,
      child: InkWell(
        onTap: onTap,
        child: SizedBox(
          height: 108,
          child: Row(
            children: [
              SizedBox(
                width: 108,
                height: 108,
                child: product != null
                    ? Container(
                        color: Colors.white,
                        alignment: Alignment.center,
                        child: ProductVisual(
                          product: product!,
                          size: 86,
                          showOrganicBadge: false,
                        ),
                      )
                    : clean == null
                        ? Container(
                            color: const Color(0xFFEAF3E7),
                            alignment: Alignment.center,
                            child: Icon(
                              icon,
                              color: FarmColors.green,
                              size: 30,
                            ),
                          )
                        : Image.network(
                            clean,
                            fit: BoxFit.cover,
                            errorBuilder: (_, __, ___) => Container(
                              color: const Color(0xFFEAF3E7),
