class _HpjRightRailMealPulseCard extends StatefulWidget {
  const _HpjRightRailMealPulseCard();

  @override
  State<_HpjRightRailMealPulseCard> createState() =>
      _HpjRightRailMealPulseCardState();
}

class _HpjRightRailMealPulseCardState
    extends State<_HpjRightRailMealPulseCard> {
  late Future<List<HpjMealPost>> _postsFuture;
  late Future<HpjMealHabit> _habitFuture;

  @override
  void initState() {
    super.initState();
    _postsFuture = fetchHpjMealPulse(limit: 6);
    _habitFuture = fetchHpjMealHabit();
  }

  Future<void> _open({bool composer = false}) async {
    await Navigator.of(context).push<void>(
      MaterialPageRoute<void>(
        builder: (_) => HpjMealPulseScreen(
          openComposerOnStart: composer,
        ),
      ),
    );
    if (!mounted) return;
    setState(() {
      _postsFuture = fetchHpjMealPulse(limit: 6);
      _habitFuture = fetchHpjMealHabit();
    });
  }

  @override
  Widget build(BuildContext context) {
    return FutureBuilder<List<HpjMealPost>>(
      future: _postsFuture,
      builder: (context, postSnapshot) {
        final posts = postSnapshot.data ?? const <HpjMealPost>[];
        return FutureBuilder<HpjMealHabit>(
          future: _habitFuture,
          builder: (context, habitSnapshot) {
            final habit = habitSnapshot.data ??
                const HpjMealHabit(streakDays: 0, postedToday: false);

            return Material(
              color: Colors.white,
              borderRadius: BorderRadius.circular(15),
              child: InkWell(
                onTap: () => _open(),
                borderRadius: BorderRadius.circular(15),
                child: Container(
                  width: double.infinity,
                  padding: const EdgeInsets.all(11),
                  decoration: BoxDecoration(
                    borderRadius: BorderRadius.circular(15),
                    border: Border.all(color: HpjWebUi.border),
                  ),
                  child: Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      Row(
                        children: [
                          Container(
                            width: 35,
                            height: 35,
                            decoration: BoxDecoration(
                              color: FarmColors.primarySoft,
                              borderRadius: BorderRadius.circular(11),
                            ),
                            child: const Icon(
                              Icons.restaurant_menu_rounded,
                              color: FarmColors.deepGreen,
                              size: 18,
                            ),
                          ),
                          const SizedBox(width: 9),
                          const Expanded(
                            child: Column(
                              crossAxisAlignment: CrossAxisAlignment.start,
                              children: [
                                Text(
                                  'Meal Pulse',
                                  style: TextStyle(
                                    color: FarmColors.deepGreen,
                                    fontSize: 12.5,
                                    fontWeight: FontWeight.w900,
                                  ),
                                ),
                                SizedBox(height: 1),
                                Text(
                                  'See what Jamaica is eating today.',
                                  style: TextStyle(
                                    color: FarmColors.mutedText,
                                    fontSize: 7.4,
                                    fontWeight: FontWeight.w600,
                                  ),
                                ),
                              ],
                            ),
                          ),
                          if (habit.postedToday)
                            Container(
                              padding: const EdgeInsets.symmetric(
                                horizontal: 7,
                                vertical: 4,
                              ),
                              decoration: BoxDecoration(
                                color: const Color(0xFFE5F4E6),
                                borderRadius: BorderRadius.circular(999),
                              ),
                              child: Text(
                                '${habit.streakDays}d',
                                style: const TextStyle(
                                  color: FarmColors.success,
                                  fontSize: 6.9,
                                  fontWeight: FontWeight.w900,
                                ),
                              ),
                            ),
                        ],
                      ),
                      const SizedBox(height: 9),
                      if (posts.isNotEmpty)
                        Row(
                          children: posts.take(4).map((post) {
                            return Expanded(
                              child: Padding(
                                padding: const EdgeInsets.only(right: 5),
                                child: ClipRRect(
                                  borderRadius: BorderRadius.circular(9),
                                  child: SizedBox(
                                    height: 42,
                                    child: post.imageUrl.isEmpty
                                        ? Container(
                                            color: FarmColors.primarySoft,
                                            child: const Icon(
                                              Icons.restaurant_rounded,
                                              size: 16,
                                              color: FarmColors.primary,
                                            ),
                                          )
                                        : Image.network(
                                            post.imageUrl,
                                            fit: BoxFit.cover,
                                            errorBuilder: (_, __, ___) =>
                                                Container(
                                              color: FarmColors.primarySoft,
                                              child: const Icon(
                                                Icons.restaurant_rounded,
                                                size: 16,
                                                color: FarmColors.primary,
                                              ),
                                            ),
                                          ),
                                  ),
                                ),
                              ),
                            );
                          }).toList(),
                        )
                      else
                        Text(
                          habit.postedToday
                              ? 'You showed up today. See what the community is cooking.'
                              : _hpjMealDailyPrompt(),
                          maxLines: 2,
                          overflow: TextOverflow.ellipsis,
                          style: const TextStyle(
                            color: FarmColors.mutedText,
                            fontSize: 7.7,
                            height: 1.3,
                            fontWeight: FontWeight.w600,
                          ),
                        ),
                      const SizedBox(height: 8),
                      Row(
                        children: [
                          Expanded(
                            child: Text(
                              habit.postedToday
                                  ? 'You posted today'
                                  : 'Your plate belongs here too',
                              maxLines: 1,
                              overflow: TextOverflow.ellipsis,
                              style: const TextStyle(
                                color: FarmColors.deepGreen,
                                fontSize: 7.5,
                                fontWeight: FontWeight.w800,
                              ),
                            ),
                          ),
                          TextButton(
                            onPressed: () => _open(
                              composer: !habit.postedToday,
                            ),
                            child: Text(
                              habit.postedToday ? 'View' : 'Post meal',
                            ),
                          ),
                        ],
                      ),
                    ],
                  ),
                ),
              ),
            );
          },
        );
      },
    );
  }
}

class _HpjRightRailGrowTogetherCard extends StatefulWidget {
