class _HPJImageCategoryCard extends StatelessWidget {
  final PopularCategorySummary category;
  final List<Product> previewProducts;
  final VoidCallback onTap;

  const _HPJImageCategoryCard({
    required this.category,
    required this.previewProducts,
    required this.onTap,
  });

  String get _key => category.name.trim().toLowerCase();

  String get _displayName {
    switch (_key) {
      case 'herbs':
        return 'Herbs & Seasonings';

      case 'ground provisions':
        return 'Ground Provisions';

      case 'other':
        return 'Pantry & Specialty';

      case 'prepared foods':
        return 'Prepared Foods';

      default:
        return category.name;
    }
  }

  String get _tagline {
    switch (_key) {
      case 'vegetables':
      case 'vegetable':
        return 'FRESH. LOCAL. NOURISHING.';

      case 'fruits':
      case 'fruit':
        return 'SWEETNESS FROM OUR SOIL.';

      case 'ground provisions':
      case 'ground provision':
        return 'OUR ROOTS. YOUR TABLE.';

      case 'herbs':
      case 'herb':
        return 'BOLD FLAVOURS. REAL GOODNESS.';

      case 'eggs':
      case 'egg':
        return 'FARM FRESH. EVERYDAY GOODNESS.';

      case 'prepared foods':
      case 'prepared food':
        return 'LOCAL FLAVOUR. READY TO ENJOY.';

      case 'grains':
      case 'grain':
        return 'WHOLESOME STAPLES. SIMPLY GOOD.';

      default:
        return 'FRESH PICKS FROM JAMAICA.';
    }
  }

  Widget _imageTile(
    String? imageUrl, {
    double radius = 8,
  }) {
    return ClipRRect(
      borderRadius: BorderRadius.circular(radius),
      child: Container(
        color: FarmColors.cardSoft,
        child: imageUrl == null || imageUrl.isEmpty
            ? Container(
                color: const Color(0xFFF2F5EF),
              )
            : Image.network(
                imageUrl,
                fit: BoxFit.cover,
                alignment: Alignment.center,
                gaplessPlayback: true,
                cacheWidth: 420,
                filterQuality: FilterQuality.medium,
                errorBuilder: (
                  context,
                  error,
                  stackTrace,
                ) {
                  return Container(
                    color: const Color(0xFFF2F5EF),
                  );
                },
              ),
      ),
    );
  }

  Widget _compactImageCollage(List<String> images) {
    if (images.isEmpty) {
      return Container(
        color: FarmColors.cardSoft,
      );
    }

    if (images.length == 1) {
      return _imageTile(images[0]);
    }

    if (images.length == 2) {
      return Row(
        children: [
          Expanded(
            child: _imageTile(images[0]),
          ),
          const SizedBox(width: 6),
          Expanded(
            child: _imageTile(images[1]),
          ),
        ],
      );
    }

    if (images.length == 3) {
      return Row(
        children: [
          Expanded(
            child: _imageTile(images[0]),
          ),
          const SizedBox(width: 6),
          Expanded(
            child: Column(
              children: [
                Expanded(
                  child: _imageTile(images[1]),
                ),
                const SizedBox(height: 6),
                Expanded(
                  child: _imageTile(images[2]),
                ),
              ],
            ),
          ),
        ],
      );
    }

    return Column(
      children: [
        Expanded(
          child: Row(
            children: [
              Expanded(
                child: _imageTile(images[0]),
              ),
              const SizedBox(width: 4),
              Expanded(
                child: _imageTile(images[1]),
              ),
            ],
          ),
        ),
        const SizedBox(height: 4),
        Expanded(
          child: Row(
            children: [
              Expanded(
                child: _imageTile(images[2]),
              ),
              const SizedBox(width: 4),
              Expanded(
                child: _imageTile(images[3]),
              ),
            ],
          ),
        ),
      ],
    );
  }

  Widget _desktopImageCollage(List<String> images) {
    if (images.isEmpty) {
      return Container(
        color: const Color(0xFFF1F5EF),
      );
    }

    if (images.length == 1) {
      return _imageTile(
        images[0],
        radius: 13,
      );
    }

    if (images.length == 2) {
      return Row(
        children: [
          Expanded(
            flex: 6,
            child: _imageTile(
              images[0],
              radius: 13,
            ),
          ),
          const SizedBox(width: 4),
          Expanded(
            flex: 4,
            child: _imageTile(
              images[1],
              radius: 13,
            ),
          ),
        ],
      );
    }

    return Row(
      children: [
        Expanded(
          flex: 58,
          child: _imageTile(
            images[0],
            radius: 13,
          ),
        ),
        const SizedBox(width: 4),
        Expanded(
          flex: 42,
          child: Column(
            children: [
              Expanded(
                child: _imageTile(
                  images[1],
                  radius: 13,
                ),
              ),
              const SizedBox(height: 4),
              Expanded(
                child: _imageTile(
                  images[2],
                  radius: 13,
                ),
              ),
            ],
          ),
        ),
      ],
    );
  }

  @override
  Widget build(BuildContext context) {
    final desktopWeb =
        kIsWeb && MediaQuery.sizeOf(context).width >= 1100;

    final imageUrls = previewProducts
        .map(
          (product) => cleanHostedImageUrl(product.imageUrl),
        )
        .whereType<String>()
        .where((url) => url.isNotEmpty)
        .take(desktopWeb ? 3 : 4)
        .toList();

    final count = category.availableItemCount;
    final countLabel = count == 1 ? '1 item' : '$count items';

    if (!desktopWeb) {
      return Material(
        color: Colors.transparent,
        child: InkWell(
          onTap: onTap,
          borderRadius: BorderRadius.circular(18),
          child: Ink(
            decoration: BoxDecoration(
              color: FarmColors.card,
              borderRadius: BorderRadius.circular(18),
              border: Border.all(
                color: FarmColors.line.withOpacity(0.90),
              ),
              boxShadow: [
                BoxShadow(
                  color: Colors.black.withOpacity(0.03),
                  blurRadius: 10,
                  offset: const Offset(0, 3),
                ),
              ],
            ),
            child: ClipRRect(
              borderRadius: BorderRadius.circular(18),
              child: Column(
                children: [
                  Expanded(
                    child: Padding(
                      padding: const EdgeInsets.fromLTRB(
                        6,
                        6,
                        6,
                        0,
                      ),
                      child: _compactImageCollage(imageUrls),
                    ),
                  ),
                  Padding(
                    padding: const EdgeInsets.fromLTRB(
                      10,
                      8,
                      9,
                      10,
                    ),
                    child: Row(
                      children: [
                        Expanded(
                          child: Text(
                            _displayName,
                            maxLines: 2,
                            overflow: TextOverflow.ellipsis,
                            style: const TextStyle(
                              color: FarmColors.ink,
                              fontSize: 12.5,
                              fontWeight: FontWeight.w900,
                              height: 1.04,
                              letterSpacing: -0.15,
