  void _applyShopParishRequest() {
    final requested = hpjShopParishRequest.value?.trim() ?? '';
    if (requested.isEmpty || !mounted) return;

    final canonical = _canonicalJamaicaParish(requested);
    if (canonical.isEmpty || !_jamaicaParishes.contains(canonical)) {
      hpjShopParishRequest.value = null;
      return;
    }

    setState(() {
      selectedNearArea = canonical;
      nearAreaReady = true;
      selectedCategory = 'All';
      selectedShopFilter = 'All items';
      selectedShopNutrient = 'All';
      selectedShopAvailability = 'Any availability';
      selectedShopPrice = 'Any price';
      selectedShopFarm = 'All farms';
      selectedShopSpecial = 'All';
      selectedSort = 'Recommended';
      searchController.clear();
    });

    unawaited(HpjSmartLocalStore.writeString('shop_near_area', canonical));

    if (hpjCustomerParishPreference.value != canonical) {
      hpjCustomerParishPreference.value = canonical;
    }

    hpjShopParishRequest.value = null;
  }

  @override
  void initState() {
    super.initState();
    selectedCategory = normalizeProductCategory(widget.initialCategory);
    searchController.addListener(() {
      searchDebounce?.cancel();
      searchDebounce = Timer(AppPerformanceConfig.debounce, () {
        if (mounted) setState(() {});
      });
    });
    mealIngredientShopSearchRequest.addListener(_applyMealIngredientSearch);
    hpjShopParishRequest.addListener(_applyShopParishRequest);

harvestPulseShopRequest.addListener(
  _applyHarvestPulseShopRequest,
);
WidgetsBinding.instance.addPostFrameCallback((_) {
  _applyHarvestPulseShopRequest();
  _applyShopParishRequest();
});
loadProducts();
    _loadSavedFavoritesForShop();
    unawaited(_restoreNearYouArea());
  }

  String _cleanNearArea(String value) {
    var clean = value.trim();
    if (clean.contains('•')) clean = clean.split('•').first.trim();
    if (clean.contains(' - ')) clean = clean.split(' - ').first.trim();
    return clean;
  }

  String _canonicalJamaicaParish(String value) {
    final raw = _cleanNearArea(value);
    if (raw.isEmpty) return '';

    String key(String input) => input
        .trim()
        .toLowerCase()
        .replaceAll('saint ', 'st ')
        .replaceAll('.', '')
        .replaceAll(RegExp(r'\s+'), ' ');

    final normalized = key(raw);
    for (final parish in _jamaicaParishes) {
      if (key(parish) == normalized) return parish;
    }

    if (normalized == 'st elizabeth parish') return 'St. Elizabeth';
    if (normalized == 'st james parish') return 'St. James';
    if (normalized == 'st ann parish') return 'St. Ann';
    if (normalized == 'st catherine parish') return 'St. Catherine';
    if (normalized == 'st mary parish') return 'St. Mary';
    if (normalized == 'st andrew parish') return 'St. Andrew';
    if (normalized == 'st thomas parish') return 'St. Thomas';

    return raw;
  }

  String get _selectedMapParish {
    final parish = _canonicalJamaicaParish(selectedNearArea);
    return _jamaicaParishes.contains(parish) ? parish : 'St. Elizabeth';
  }

  Future<void> _restoreNearYouArea() async {
    try {
      final savedArea = await HpjSmartLocalStore.readString('shop_near_area');
      final checkoutArea = await HpjSmartLocalStore.readString('checkout_zone');
      final candidate = _cleanNearArea(
        (savedArea ?? '').trim().isNotEmpty
            ? savedArea!
            : (checkoutArea ?? '').trim().isNotEmpty
                ? checkoutArea!
                : 'St. Elizabeth',
      );

      if (!mounted) return;

      final canonical = _canonicalJamaicaParish(candidate);
      final next = canonical.isEmpty ? 'St. Elizabeth' : canonical;

      setState(() {
        selectedNearArea = next;
        nearAreaReady = true;
      });

      final shared = _hpjCanonicalCustomerParish(next);
      if (hpjCustomerParishPreference.value != shared) {
        hpjCustomerParishPreference.value = shared;
      }
    } catch (_) {
      if (!mounted) return;
      setState(() => nearAreaReady = true);
    }
  }

  List<String> _nearAreaOptions() {
    final output = List<String>.from(_jamaicaParishes);
    final current = _canonicalJamaicaParish(selectedNearArea);

    output.sort((a, b) {
      if (a == current) return -1;
      if (b == current) return 1;

      final aCount = products
          .where((product) =>
              product.canAddToCart &&
              _canonicalJamaicaParish((product.parish ?? '').trim()) == a)
          .length;
      final bCount = products
          .where((product) =>
              product.canAddToCart &&
              _canonicalJamaicaParish((product.parish ?? '').trim()) == b)
          .length;

      if (aCount != bCount) return bCount.compareTo(aCount);
      return a.toLowerCase().compareTo(b.toLowerCase());
    });

    return output;
  }

  bool _productIsNearArea(Product product) {
    final productArea = _canonicalJamaicaParish((product.parish ?? '').trim());
    final selectedArea = _canonicalJamaicaParish(selectedNearArea);
    if (productArea.isEmpty || selectedArea.isEmpty) return false;
    return productArea == selectedArea;
  }

  List<Product> _nearYouProducts() {
    final output = products
        .where(isVisibleCustomerProduct)
        .where((product) => product.canAddToCart)
        .where(_productIsNearArea)
        .toList();

    output.sort((a, b) {
      if (a.isLowStock != b.isLowStock) return a.isLowStock ? -1 : 1;
      if (a.hasActiveDiscount != b.hasActiveDiscount) {
        return a.hasActiveDiscount ? -1 : 1;
      }
      return a.name.toLowerCase().compareTo(b.name.toLowerCase());
    });
    return output;
  }

