                  child: ListView.separated(
                    shrinkWrap: true,
                    itemCount: options.length,
                    separatorBuilder: (_, __) => Divider(
                      height: 1,
                      color: FarmColors.line.withOpacity(.70),
                    ),
                    itemBuilder: (context, index) {
                      final area = options[index];
                      final selected = area == selectedNearArea;
                      final count = products
                          .where((product) =>
                              product.canAddToCart &&
                              _canonicalJamaicaParish((product.parish ?? '').trim()) ==
                                  area)
                          .length;
                      return ListTile(
                        contentPadding: const EdgeInsets.symmetric(horizontal: 4),
                        leading: Icon(
                          selected
                              ? Icons.location_on_rounded
                              : Icons.location_on_outlined,
                          color: selected ? FarmColors.green : FarmColors.mutedText,
                        ),
                        title: Text(
                          area,
                          style: TextStyle(
                            color: FarmColors.ink,
                            fontWeight: selected ? FontWeight.w900 : FontWeight.w700,
                          ),
                        ),
                        subtitle: Text(
                          '$count fresh ${count == 1 ? 'item' : 'items'} available',
                          style: const TextStyle(
                            color: FarmColors.mutedText,
                            fontSize: 10.5,
                            fontWeight: FontWeight.w600,
                          ),
                        ),
                        trailing: selected
                            ? const Icon(Icons.check_circle_rounded, color: FarmColors.green)
                            : const Icon(Icons.chevron_right_rounded),
                        onTap: () => Navigator.pop(sheetContext, area),
                      );
                    },
                  ),
                ),
              ],
            ),
          ),
        );
      },
    );

    if (!mounted || picked == null || picked.trim().isEmpty) return;
    final canonical = _canonicalJamaicaParish(picked);
    setState(
      () => selectedNearArea =
          canonical.isEmpty ? picked.trim() : canonical,
    );

    unawaited(
      HpjSmartLocalStore.writeString(
        'shop_near_area',
        selectedNearArea,
      ),
    );

    final shared = _hpjCanonicalCustomerParish(selectedNearArea);
    if (hpjCustomerParishPreference.value != shared) {
      hpjCustomerParishPreference.value = shared;
    }
