    }

    Widget compactCard() {
      return Container(
        clipBehavior: Clip.antiAlias,
        decoration: BoxDecoration(
          color: muted ? FarmColors.cardSoft : const Color(0xFFFFFEFC),
          borderRadius: BorderRadius.circular(22),
          border: Border.all(
            color: muted
                ? FarmColors.danger.withOpacity(0.12)
                : FarmColors.line.withOpacity(0.82),
          ),
          boxShadow: [
            BoxShadow(
              color: FarmColors.shadow.withOpacity(muted ? 0.02 : 0.055),
              blurRadius: 16,
              offset: const Offset(0, 7),
            ),
          ],
        ),
        child: Material(
          color: Colors.transparent,
          child: InkWell(
            onTap: onOpenDetails,
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                AspectRatio(
                  aspectRatio: desktopWeb ? 1.30 : 1.10,
                  child: premiumImage(compact: true),
                ),
                Padding(
                  padding: EdgeInsets.fromLTRB(
                    desktopWeb ? 10 : 11,
                    desktopWeb ? 9 : 11,
                    desktopWeb ? 10 : 11,
                    desktopWeb ? 10 : 12,
                  ),
                  child: Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
