  Widget _desktopCartLineCard(
    CartLine line,
  ) {
    final product = line.product;
    final farmName =
        (product.farmName ??
                product.farmerName ??
                '')
            .trim();
    final unit =
        (product.unit ?? '').trim();
    final lineTotal =
        product.effectivePrice * line.quantity;
    final lineSavings =
        ((product.originalPriceValue -
                    product.effectivePrice) *
                line.quantity)
            .clamp(
              0,
              double.infinity,
            )
            .toDouble();

    return Container(
      margin: const EdgeInsets.only(
        bottom: 12,
      ),
      padding: const EdgeInsets.all(14),
      decoration: BoxDecoration(
        color: Colors.white,
        borderRadius:
            BorderRadius.circular(16),
        border: Border.all(
          color: product.canAddToCart
              ? const Color(0xFFDDE5DD)
              : FarmColors.danger
                  .withOpacity(.24),
