class OrdersScreen extends StatefulWidget {
  final VoidCallback? onBackToHome;
  final void Function(Product product)? onAddToCart;
  final VoidCallback? onOpenMyBox;

  const OrdersScreen({
    super.key,
    this.onBackToHome,
    this.onAddToCart,
    this.onOpenMyBox,
  });

  @override
  State<OrdersScreen> createState() => _OrdersScreenState();
}

class _OrdersScreenState extends State<OrdersScreen> {
  StreamSubscription<AuthState>? _authSubscription;
  late Future<List<FarmOrder>> _ordersFuture;

  // MVP Orders controls: status + sort. Server query remains unchanged;
  // filters and ordering are applied safely in the customer UI.
  String _orderFilter = 'current';
  String _orderSort = 'recent';

  bool _orderMatchesFilter(FarmOrder order) {
    final status = order.status.trim().toLowerCase();
    final isReady = status == 'ready' || status == 'ready_for_pickup';
    final isCompleted = status == 'completed' || status == 'delivered';
    final isCancelled = status == 'cancelled' ||
        status == 'canceled' ||
        status == 'rejected';
    final isCurrent = !isCompleted && !isCancelled;

    switch (_orderFilter) {
      case 'current':
      case 'mobile_active':
        return isCurrent;
      case 'ready':
        return isReady;
      case 'completed':
        return isCompleted;
      case 'cancelled':
        return isCancelled;
      case 'history':
        return isCompleted || isCancelled;
      case 'active':
        return !isReady && isCurrent;
      case 'all':
      default:
        return true;
    }
  }

  String get _emptyFilterMessage {
    switch (_orderFilter) {
      case 'current':
      case 'mobile_active':
      case 'active':
        return 'You do not have any current orders right now.';
      case 'ready':
        return 'You do not have any orders ready for pickup right now.';
      case 'completed':
        return 'Your completed orders will appear here.';
      case 'cancelled':
        return 'You do not have any cancelled orders.';
      case 'history':
        return 'Your completed and past orders will appear here.';
      default:
        return 'No orders match this filter.';
    }
  }

  List<FarmOrder> _sortCustomerOrders(List<FarmOrder> source) {
    final output = List<FarmOrder>.from(source);
    DateTime safeDate(FarmOrder order) =>
        order.createdAt ?? DateTime.fromMillisecondsSinceEpoch(0);

    switch (_orderSort) {
      case 'oldest':
        output.sort((a, b) => safeDate(a).compareTo(safeDate(b)));
        break;
      case 'recent':
      default:
        output.sort((a, b) => safeDate(b).compareTo(safeDate(a)));
        break;
    }
    return output;
  }

  String get _orderFilterLabel {
    switch (_orderFilter) {
      case 'current':
      case 'mobile_active':
        return 'Current';
      case 'ready':
        return 'Ready';
      case 'completed':
        return 'Completed';
      case 'cancelled':
        return 'Cancelled';
      case 'history':
        return 'History';
      case 'all':
      default:
        return 'All orders';
    }
  }

  String get _orderSortLabel => _orderSort == 'oldest'
      ? 'Oldest first'
      : 'Most recent';

  int get _activeOrderControlCount {
    var count = 0;
    if (_orderFilter != 'current') count++;
    if (_orderSort != 'recent') count++;
    return count;
  }

  Future<void> _showOrderFilterSheet({
    required int allCount,
    required int currentCount,
    required int readyCount,
    required int completedCount,
    required int cancelledCount,
    required int historyCount,
  }) async {
    await showModalBottomSheet<void>(
      context: context,
      isScrollControlled: true,
      backgroundColor: Colors.transparent,
      builder: (sheetContext) {
        return StatefulBuilder(
          builder: (context, sheetSetState) {
            Widget choice({
              required String label,
              required bool selected,
              required VoidCallback onTap,
              int? count,
              IconData? icon,
            }) {
              return ChoiceChip(
                selected: selected,
                onSelected: (_) {
                  onTap();
                  sheetSetState(() {});
                },
                avatar: icon == null
                    ? null
                    : Icon(
                        icon,
                        size: 15,
                        color: selected ? Colors.white : FarmColors.green,
                      ),
                label: Text(count == null ? label : '$label  $count'),
                selectedColor: FarmColors.green,
                backgroundColor: FarmColors.primarySoft.withOpacity(.55),
                labelStyle: TextStyle(
                  color: selected ? Colors.white : FarmColors.deepGreen,
                  fontSize: 11.3,
                  fontWeight: FontWeight.w900,
                ),
                side: BorderSide(
                  color: selected
                      ? FarmColors.green
                      : FarmColors.green.withOpacity(.12),
                ),
                shape: RoundedRectangleBorder(
                  borderRadius: BorderRadius.circular(999),
                ),
              );
            }

            return SafeArea(
              top: false,
              child: Padding(
                padding: const EdgeInsets.fromLTRB(12, 0, 12, 12),
                child: Container(
                  decoration: BoxDecoration(
                    color: const Color(0xFFFFFEFB),
