  Widget _buildOrdersOverview(List<FarmOrder> orders) {
    var active = 0;
    var ready = 0;
    var completed = 0;

    for (final order in orders) {
      final status = order.status.trim().toLowerCase();
      final isReady = status == 'ready' || status == 'ready_for_pickup';
      final isCompleted = status == 'completed' || status == 'delivered';
      final isCancelled = status == 'cancelled' ||
          status == 'canceled' ||
          status == 'rejected';

      if (isReady) {
        ready++;
      } else if (isCompleted) {
        completed++;
      } else if (!isCancelled) {
        active++;
      }
    }

    return Container(
      width: double.infinity,
      padding: const EdgeInsets.fromLTRB(18, 18, 18, 16),
      decoration: BoxDecoration(
        gradient: const LinearGradient(
          begin: Alignment.topLeft,
          end: Alignment.bottomRight,
          colors: [
            Color(0xFF073F2C),
            Color(0xFF145A3C),
          ],
        ),
        borderRadius: BorderRadius.circular(26),
        boxShadow: [
          BoxShadow(
            color: const Color(0xFF073F2C).withOpacity(0.16),
            blurRadius: 26,
            offset: const Offset(0, 12),
          ),
        ],
      ),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Row(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              Container(
                width: 46,
                height: 46,
                decoration: BoxDecoration(
                  color: Colors.white.withOpacity(0.11),
                  borderRadius: BorderRadius.circular(15),
                ),
                child: const Icon(
                  Icons.receipt_long_outlined,
                  color: Colors.white,
                  size: 24,
                ),
              ),
              const SizedBox(width: 12),
              Expanded(
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    const Text(
                      'Your harvest journey',
                      style: TextStyle(
                        color: Colors.white,
                        fontSize: 20,
                        fontWeight: FontWeight.w900,
                        letterSpacing: -0.4,
                      ),
                    ),
                    const SizedBox(height: 4),
                    Text(
                      'Follow every order from checkout to collection or delivery.',
                      style: TextStyle(
                        color: Colors.white.withOpacity(0.78),
                        fontSize: 12.2,
                        height: 1.35,
                        fontWeight: FontWeight.w600,
                      ),
                    ),
                  ],
                ),
              ),
            ],
          ),
          const SizedBox(height: 17),
          Row(
            children: [
              _overviewMetric(
                icon: Icons.sync_rounded,
                value: '$active',
                label: 'Active',
              ),
              const SizedBox(width: 9),
              _overviewMetric(
                icon: Icons.inventory_2_outlined,
                value: '$ready',
                label: 'Ready',
              ),
              const SizedBox(width: 9),
