  const OrderDetailsScreen({
    super.key,
    required this.orderId,
    this.onAddToCart,
    this.onOpenMyBox,
    this.backToOrders = false,
  });

  @override
  State<OrderDetailsScreen> createState() => _OrderDetailsScreenState();
}

class _OrderDetailsScreenState extends State<OrderDetailsScreen> {
  late Future<OrderDetails?> _orderFuture;
  bool _loadingReorder = false;
  @override
  void initState() {
    super.initState();
    _orderFuture = fetchOrderDetails(widget.orderId);
  }

  Future<void> _refreshOrderDetails() async {
    final future = fetchOrderDetails(widget.orderId);
    if (mounted) {
      setState(() {
        _orderFuture = future;
      });
    }
    await future;
  }

  int _statusIndex(String status) {
    switch (status) {
      case 'pending':
        return 0;
      case 'preparing':
        return 1;
      case 'ready':
      case 'ready_for_pickup':
      case 'out_for_delivery':
        return 2;
      case 'delivered':
        return 3;
      default:
        return 0;
    }
  }

  Color _detailStatusColor(String rawStatus) {
    switch (rawStatus.trim().toLowerCase()) {
      case 'delivered':
      case 'completed':
        return const Color(0xFFBFE2C8);
      case 'ready':
      case 'ready_for_pickup':
        return const Color(0xFFD5E9CB);
      case 'out_for_delivery':
        return const Color(0xFFCDE7F0);
      case 'preparing':
      case 'confirmed':
        return const Color(0xFFFFE5B8);
      case 'cancelled':
      case 'canceled':
      case 'rejected':
        return const Color(0xFFFFD8D5);
      default:
        return const Color(0xFFE6EEE9);
    }
  }

  Color _detailStatusTextColor(String rawStatus) {
    switch (rawStatus.trim().toLowerCase()) {
      case 'delivered':
      case 'completed':
      case 'ready':
      case 'ready_for_pickup':
        return const Color(0xFF0B4C36);
      case 'out_for_delivery':
        return const Color(0xFF15566C);
      case 'preparing':
      case 'confirmed':
        return const Color(0xFF805512);
      case 'cancelled':
      case 'canceled':
      case 'rejected':
        return const Color(0xFF9E2A25);
      default:
        return const Color(0xFF506159);
    }
  }

  String _prettyOrderValue(String value) {
    final clean = value.replaceAll('_', ' ').trim();
    if (clean.isEmpty) return value;
    return clean
        .split(' ')
        .where((part) => part.trim().isNotEmpty)
        .map((part) {
          final lower = part.toLowerCase();
          return '${lower[0].toUpperCase()}${lower.substring(1)}';
        })
        .join(' ');
  }

