class NotificationsScreen extends StatefulWidget {
  const NotificationsScreen({super.key});

  @override
  State<NotificationsScreen> createState() => _NotificationsScreenState();
}

class _NotificationsScreenState extends State<NotificationsScreen> {
  int refreshKey = 0;
  String selectedFilter = 'all';
  bool markingRead = false;

  final Set<String> selectedNotificationIds = <String>{};

  bool get isSelecting => selectedNotificationIds.isNotEmpty;
  void toggleNotificationSelection(
    FarmNotification notice,
  ) {
    if (notice.id.trim().isEmpty) return;

    setState(() {
      if (selectedNotificationIds.contains(notice.id)) {
        selectedNotificationIds.remove(notice.id);
      } else {
        selectedNotificationIds.add(notice.id);
      }
    });
  }

  void clearNotificationSelection() {
    setState(() {
      selectedNotificationIds.clear();
    });
  }

  Future<void> deleteNotificationsByIds(
    Set<String> notificationIds,
  ) async {
    final user = supabase.auth.currentUser;

    if (user == null || notificationIds.isEmpty) {
      return;
    }

    final ids = notificationIds.where((id) => id.trim().isNotEmpty).toList();

    if (ids.isEmpty) return;

    await supabase.from('notifications').delete().inFilter('id', ids);

    FarmDataCache.notifications = null;
  }


  Future<void> deleteSelectedNotifications() async {
    if (selectedNotificationIds.isEmpty) return;

    final count = selectedNotificationIds.length;

    final confirmed = await showDialog<bool>(
      context: context,
      builder: (dialogContext) {
        return AlertDialog(
          title: Text(
            count == 1 ? 'Delete update?' : 'Delete $count updates?',
          ),
          content: const Text(
            'The selected updates will be removed from your inbox.',
          ),
          actions: [
            TextButton(
              onPressed: () {
                Navigator.pop(dialogContext, false);
              },
              child: const Text('Cancel'),
            ),
            FilledButton(
              onPressed: () {
                Navigator.pop(dialogContext, true);
              },
              child: const Text('Delete'),
            ),
          ],
        );
      },
    );

    if (confirmed != true) return;

    final ids = Set<String>.from(selectedNotificationIds);

    try {
      await deleteNotificationsByIds(ids);

      if (!mounted) return;

      setState(() {
        selectedNotificationIds.clear();
        refreshKey++;
      });

      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(
          content: Text(
            count == 1 ? 'Update deleted' : '$count updates deleted',
          ),
        ),
      );
    } catch (error) {
      debugPrint(
        'DELETE NOTIFICATION ERROR: $error',
      );

      if (!mounted) return;

      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(
          content: Text(
            'Delete failed: $error',
          ),
        ),
      );
    }
  }

  Future<void> markReadAndRefresh() async {
    if (markingRead) return;
    setState(() => markingRead = true);
    try {
      await markNotificationsRead();
      FarmDataCache.notifications = null;
      if (mounted) setState(() => refreshKey++);
    } finally {
      if (mounted) setState(() => markingRead = false);
    }
  }

  Future<void> refreshNotifications() async {
    FarmDataCache.notifications = null;
    if (mounted) setState(() => refreshKey++);
  }

  Future<void> _openNotification(FarmNotification notice) async {
    final opened = await PushNotificationService.openFarmNotification(
      notice,
      context: context,
    );

    if (!mounted) return;

    if (opened) {
      FarmDataCache.notifications = null;
      setState(() {
        refreshKey++;
      });
      return;
    }

    ScaffoldMessenger.of(context).showSnackBar(
      const SnackBar(
        content: Text(
          'This update is still unread because its destination could not be opened.',
        ),
      ),
    );
  }

  String _noticeType(FarmNotification notice) =>
      notice.type.trim().toLowerCase();

  String _noticeAction(FarmNotification notice) =>
      hpjCanonicalNotificationActionType(notice.actionType);

  bool _isOrderNotice(FarmNotification notice) {
    final type = _noticeType(notice);
    final action = _noticeAction(notice);
    return notice.hasOrderLink ||
        const <String>{
          'order',
          'payment',
          'delivery',
        }.contains(type) ||
        const <String>{
          'order',
          'admin_customer_order',
          'wholesale_order',
          'admin_wholesale_order',
          'admin_wholesale_payment',
        }.contains(action);
  }

  bool _isSupportNotice(FarmNotification notice) {
    final type = _noticeType(notice);
    final action = _noticeAction(notice);
    return type == 'support' ||
        type == 'review' ||
        const <String>{
          'support_chat',
          'admin_support_chat',
          'admin_review',
        }.contains(action);
  }

  bool _isStockNotice(FarmNotification notice) {
    final type = _noticeType(notice);
    final action = _noticeAction(notice);
    return type == 'stock' ||
        type == 'product_ready' ||
        const <String>{
          'customer_product',
          'wholesale_product',
          'admin_inventory',
          'admin_product_approval',
        }.contains(action);
  }

  bool _isWatchingNotice(FarmNotification notice) {
    final type = _noticeType(notice);
    return type == 'watch' || type == 'price_drop';
  }

  bool _isFarmerNotice(FarmNotification notice) {
    final type = _noticeType(notice);
    final action = _noticeAction(notice);
    return type.startsWith('farmer_') ||
        action.startsWith('farmer_') ||
        action == 'admin_farmer_application';
  }

  bool _isWholesaleNotice(FarmNotification notice) {
    final type = _noticeType(notice);
    final action = _noticeAction(notice);
    return type == 'wholesale' ||
        action.startsWith('wholesale_') ||
        action.startsWith('admin_wholesale_');
  }

  bool _matchesFilter(FarmNotification notice) {
    switch (selectedFilter) {
      case 'unread':
        return !notice.isRead;
      case 'orders':
        return _isOrderNotice(notice);
      case 'support':
        return _isSupportNotice(notice);
      case 'stock':
        return _isStockNotice(notice);
      case 'watching':
        return _isWatchingNotice(notice);
      case 'farmer':
        return _isFarmerNotice(notice);
      case 'wholesale':
        return _isWholesaleNotice(notice);
      default:
        return true;
    }
  }

  @override
  Widget build(BuildContext context) {
    final desktopWeb = HpjWebUi.isDesktop(context);

    return Scaffold(
      backgroundColor: FarmColors.background,
      appBar: AppBar(
        backgroundColor: FarmColors.background,
        leading: isSelecting
            ? IconButton(
                tooltip: 'Cancel selection',
                onPressed: clearNotificationSelection,
                icon: const Icon(
                  Icons.close_rounded,
                ),
              )
            : const BackButton(),
        title: Text(
          isSelecting
              ? '${selectedNotificationIds.length} selected'
              : (desktopWeb ? 'Notification Center' : 'Updates'),
        ),
        actions: [
          if (isSelecting)
            IconButton(
              tooltip: 'Delete selected',
              onPressed: deleteSelectedNotifications,
              icon: const Icon(
                Icons.delete_outline_rounded,
              ),
            )
          else
            IconButton(
              tooltip: 'Refresh',
              onPressed: refreshNotifications,
              icon: const Icon(
                Icons.restart_alt_rounded,
              ),
            ),
        ],
      ),
      body: FarmPage(
        child: FutureBuilder<List<FarmNotification>>(
          key: ValueKey(refreshKey),
          future: fetchFarmNotifications(
            forceRefresh: true,
          ),
          builder: (context, snapshot) {
            if (snapshot.connectionState == ConnectionState.waiting &&
                !snapshot.hasData) {
              return const SkeletonList(count: 3, height: 104);
            }

            final notifications = snapshot.data ?? const <FarmNotification>[];
            final unreadCount =
                notifications.where((notice) => !notice.isRead).length;
            final orderCount =
                notifications.where(_isOrderNotice).length;
            final supportCount =
                notifications.where(_isSupportNotice).length;
            final stockCount =
                notifications.where(_isStockNotice).length;
            final watchCount =
                notifications.where(_isWatchingNotice).length;
            final farmerCount =
                notifications.where(_isFarmerNotice).length;
            final wholesaleCount =
                notifications.where(_isWholesaleNotice).length;

            final filtered = notifications.where(_matchesFilter).toList()
              ..sort((a, b) {
                if (a.isRead != b.isRead) return a.isRead ? 1 : -1;
                final aDate =
                    a.createdAt ?? DateTime.fromMillisecondsSinceEpoch(0);
                final bDate =
                    b.createdAt ?? DateTime.fromMillisecondsSinceEpoch(0);
                return bDate.compareTo(aDate);
              });

            return RefreshIndicator(
              onRefresh: refreshNotifications,
              child: ListView(
                physics: const AlwaysScrollableScrollPhysics(),
                padding: EdgeInsets.fromLTRB(
                  desktopWeb ? 22 : 18,
                  18,
                  desktopWeb ? 22 : 18,
                  120,
                ),
                children: [
                  if (desktopWeb)
                    _PremiumWebNotificationHero(
                      unreadCount: unreadCount,
                      totalCount: notifications.length,
                      orderCount: orderCount,
                      supportCount: supportCount,
                      onMarkRead:
                          unreadCount == 0 ? null : markReadAndRefresh,
                    )
                  else
                    NotificationCenterHero(
                      unreadCount: unreadCount,
                      totalCount: notifications.length,
                      markingRead: markingRead,
                      onMarkRead:
                          unreadCount == 0 ? null : markReadAndRefresh,
                    ),
                  const SizedBox(height: 16),
                  NotificationFilterBar(
                    selected: selectedFilter,
                    unreadCount: unreadCount,
                    orderCount: orderCount,
                    supportCount: supportCount,
                    stockCount: stockCount,
                    watchCount: watchCount,
                    farmerCount: farmerCount,
                    wholesaleCount: wholesaleCount,
                    onSelected: (value) =>
                        setState(() => selectedFilter = value),
                  ),
                  const SizedBox(height: 16),
                  if (notifications.isEmpty)
                    const FarmEmptyState(
                      icon: Icons.notifications_none_rounded,
                      title: 'No updates yet',
                      message:
                          'Orders, private support replies, watched products, and buyer-demand updates will appear here.',
                    )
                  else if (filtered.isEmpty)
                    FarmEmptyState(
                      icon: Icons.filter_alt_off_rounded,
                      title: 'Nothing in this view',
                      message:
                          'Try All updates to see everything across HPJ.',
                      actionLabel: 'Show all',
                      actionIcon: Icons.notifications_active_outlined,
                      onAction: () => setState(() => selectedFilter = 'all'),
                    )
                  else
                    ...filtered.map(
                      (notice) => FarmNotificationTile(
                        notice: notice,
                        selected: selectedNotificationIds.contains(notice.id),
                        onLongPress: () {
                          toggleNotificationSelection(notice);
                        },
                        onTap: isSelecting
                            ? () {
                                toggleNotificationSelection(notice);
                              }
                            : () => _openNotification(notice),
                      ),
                    ),
                ],
              ),
            );
          },
        ),
      ),
    );
  }
}

