class _ProductNutritionHighlightsCardState
    extends State<_ProductNutritionHighlightsCard> {
  bool expanded = false;

  @override
  Widget build(BuildContext context) {
    final seen = <String>{};

    final nutrients = widget.badges
        .map(_DetailNutrientBadge.tryParse)
        .whereType<_DetailNutrientBadge>()
        .where((item) {
      final key = item.nutrient.trim().toLowerCase();
      return key.isNotEmpty && seen.add(key);
    }).toList();

    if (nutrients.isEmpty) {
      return const SizedBox.shrink();
    }

    final canExpand = nutrients.length > 3;

    final visibleNutrients = expanded ? nutrients : nutrients.take(3).toList();

    return Container(
      width: double.infinity,
      padding: const EdgeInsets.all(14),
      decoration: BoxDecoration(
        color: FarmColors.cardSoft,
        borderRadius: BorderRadius.circular(20),
        border: Border.all(
          color: FarmColors.green.withOpacity(0.12),
        ),
      ),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Row(
            children: [
              Container(
                width: 36,
                height: 36,
                alignment: Alignment.center,
                decoration: BoxDecoration(
                  color: FarmColors.primarySoft,
                  shape: BoxShape.circle,
                  border: Border.all(
                    color: FarmColors.green.withOpacity(0.12),
                  ),
                ),
                child: const Icon(
                  Icons.eco_outlined,
                  color: FarmColors.green,
                  size: 19,
                ),
              ),
              const SizedBox(width: 10),
              const Expanded(
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    Text(
                      'Nutrition highlights',
                      style: TextStyle(
                        color: FarmColors.ink,
                        fontSize: 16,
                        fontWeight: FontWeight.w900,
                      ),
                    ),
                    SizedBox(height: 2),
                    Text(
                      'Tap a nutrient to view similar products.',
                      style: TextStyle(
                        color: FarmColors.mutedText,
                        fontSize: 11.5,
                        fontWeight: FontWeight.w700,
                      ),
                    ),
                  ],
                ),
              ),
            ],
          ),
          const SizedBox(height: 12),
          Wrap(
            spacing: 8,
            runSpacing: 8,
            children: visibleNutrients.map((item) {
              final canTap = widget.onNutrientTap != null;

              return Tooltip(
                message: canTap
                    ? 'View similar products with ${item.nutrient}'
                    : item.label,
                child: Material(
                  color: Colors.transparent,
                  child: InkWell(
                    borderRadius: BorderRadius.circular(999),
                    onTap: canTap
                        ? () => widget.onNutrientTap!(item.nutrient)
                        : null,
                    child: Container(
                      padding: const EdgeInsets.symmetric(
                        horizontal: 11,
                        vertical: 8,
                      ),
                      decoration: BoxDecoration(
                        color: item.backgroundColor,
                        borderRadius: BorderRadius.circular(999),
                        border: Border.all(
                          color: item.borderColor,
                          width: item.level == 'Strong' ? 1.2 : 1,
                        ),
                      ),
                      child: Row(
                        mainAxisSize: MainAxisSize.min,
                        children: [
                          Icon(
                            Icons.eco_outlined,
                            size: 14,
                            color: item.foregroundColor,
                          ),
                          const SizedBox(width: 6),
                          Text(
                            item.label,
                            style: TextStyle(
                              color: item.foregroundColor,
                              fontSize: 12,
                              fontWeight: item.level == 'Strong'
                                  ? FontWeight.w900
                                  : FontWeight.w800,
                            ),
                          ),
                          if (canTap) ...[
                            const SizedBox(width: 4),
                            Icon(
                              Icons.arrow_forward_rounded,
                              size: 14,
                              color: item.foregroundColor,
                            ),
                          ],
                        ],
                      ),
                    ),
                  ),
                ),
              );
            }).toList(),
          ),
          if (canExpand) ...[
            const SizedBox(height: 6),
            TextButton.icon(
              onPressed: () {
                setState(() {
                  expanded = !expanded;
                });
              },
              icon: Icon(
                expanded
                    ? Icons.expand_less_rounded
