          Divider(
            height: 1,
            color: FarmColors.line.withOpacity(0.75),
          ),
          const SizedBox(height: 10),
          const Row(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              Icon(
                Icons.info_outline_rounded,
                size: 16,
                color: FarmColors.mutedText,
              ),
              SizedBox(width: 7),
              Expanded(
