  Widget _checkoutRow(String label, String value, {bool strong = false}) {
    return Padding(
      padding: EdgeInsets.only(bottom: strong ? 4 : 8),
      child: Row(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Expanded(
            child: Text(
              label,
              maxLines: 2,
              overflow: TextOverflow.ellipsis,
              style: TextStyle(
                color: strong ? FarmColors.ink : FarmColors.mutedText,
                fontSize: strong ? 13.5 : 11.8,
                fontWeight: strong ? FontWeight.w900 : FontWeight.w700,
              ),
            ),
          ),
          const SizedBox(width: 10),
          Flexible(
            child: Text(
              value,
              textAlign: TextAlign.right,
              maxLines: 2,
              overflow: TextOverflow.ellipsis,
              style: TextStyle(
                color: strong ? FarmColors.green : FarmColors.ink,
                fontSize: strong ? 18 : 12,
                fontWeight: strong ? FontWeight.w900 : FontWeight.w800,
              ),
            ),
          ),
        ],
      ),
    );
  }

  Widget _selectionButton({
    required IconData icon,
    required String label,
    required VoidCallback onPressed,
  }) {
