// ============================================================================
// HPJ PHASE 97 COMPILE FIX — SHARED GROW INTELLIGENCE MODELS
//
// Admin + Farmer Phase 97 screens live in separate `part` files but share the
// same `harvest_place_app` library. These public model/service definitions are
// intentionally kept in a shared customer part so both screens can resolve the
// exact types at compile time.
//
// Social activity remains a soft signal. `hasVerifiedGap` only becomes true
// when server-returned verified demand exceeds HPJ-confirmed supply.
// ============================================================================

class HpjGrowIntelligenceSignal {
  final String cropName;
  final String category;
  final String parish;
  final String unit;
  final String? harvestCircleId;

  final int socialMentions;
  final int customerInterestCount;
  final int harvestCircleHouseholds;
  final int recentOrderCount;
  final int businessNeedCount;

  final double socialInterestScore;
  final double reservedDemand;
  final double retailOrderDemand;
  final double businessDemand;
  final double verifiedDemand;
  final double futureDemandQuantity;
  final double confirmedSupply;
  final double supplyGap;
  final double opportunityScore;

  final String confidence;
  final String signalStatus;
  final bool overplantGuard;
  final String recommendedAction;

  final DateTime? needWindowStart;
  final DateTime? needWindowEnd;

  const HpjGrowIntelligenceSignal({
    required this.cropName,
    required this.category,
    required this.parish,
    required this.unit,
    this.harvestCircleId,
    required this.socialMentions,
    required this.customerInterestCount,
    required this.harvestCircleHouseholds,
    required this.recentOrderCount,
    required this.businessNeedCount,
    required this.socialInterestScore,
    required this.reservedDemand,
    required this.retailOrderDemand,
    required this.businessDemand,
    required this.verifiedDemand,
    required this.futureDemandQuantity,
    required this.confirmedSupply,
    required this.supplyGap,
    required this.opportunityScore,
    required this.confidence,
    required this.signalStatus,
    required this.overplantGuard,
    required this.recommendedAction,
    required this.needWindowStart,
    required this.needWindowEnd,
  });

  factory HpjGrowIntelligenceSignal.fromSupabase(
    Map<String, dynamic> data,
  ) {
    double number(dynamic value) {
      if (value is num) return value.toDouble();
      return double.tryParse(value?.toString() ?? '') ?? 0;
    }

    int integer(dynamic value) {
      if (value is num) return value.toInt();
      return int.tryParse(value?.toString() ?? '') ?? 0;
    }

    bool boolean(dynamic value) {
      if (value is bool) return value;
      final clean = value?.toString().trim().toLowerCase() ?? '';
      return clean == 'true' || clean == 't' || clean == '1' || clean == 'yes';
    }

    String stringFrom(List<String> keys, {String fallback = ''}) {
      for (final key in keys) {
        final value = data[key];
        if (value == null) continue;
        final clean = value.toString().trim();
        if (clean.isNotEmpty) return clean;
      }
      return fallback;
    }

    dynamic valueFrom(List<String> keys) {
      for (final key in keys) {
        if (data.containsKey(key) && data[key] != null) return data[key];
      }
      return null;
    }

    DateTime? dateFrom(List<String> keys) {
      final value = valueFrom(keys);
      if (value == null) return null;
      if (value is DateTime) return value;
      return DateTime.tryParse(value.toString());
    }

    final verified = number(
      valueFrom(<String>[
        'future_demand_quantity',
        'verified_demand',
        'committed_demand',
        'confirmed_demand',
      ]),
    );

    final confirmed = number(
      valueFrom(<String>[
        'confirmed_supply_quantity',
        'confirmed_supply',
        'hpj_confirmed_supply',
        'verified_supply',
      ]),
    );

    final rawGap = valueFrom(<String>[
      'supply_gap',
      'verified_gap',
      'opportunity_gap',
    ]);

    final double gap = rawGap == null
        ? (verified - confirmed > 0 ? verified - confirmed : 0.0)
        : number(rawGap);

    final futureDemand = number(
      valueFrom(<String>[
        'future_demand_quantity',
        'verified_demand',
        'committed_demand',
        'confirmed_demand',
      ]),
    );

    final circleValue = stringFrom(<String>['harvest_circle_id']);
    final overplant = boolean(
      valueFrom(<String>[
        'overplant_guard',
        'overplant_warning',
        'social_only',
      ]),
    );
    final serverRecommendation = stringFrom(
      <String>['recommended_action', 'recommendation', 'action_text'],
    );
    final recommendation = serverRecommendation.isNotEmpty
        ? serverRecommendation
        : overplant
            ? 'Treat this as an interest signal only. Wait for stronger reserved or verified demand before expanding planting.'
            : gap > 0
                ? 'Review the verified demand gap and commit only the quantity your farm can confidently supply.'
                : 'Keep your expected harvest and available supply current so HPJ can match future demand accurately.';

    return HpjGrowIntelligenceSignal(
      cropName: stringFrom(
        <String>['crop_name', 'product_name', 'ingredient_name'],
        fallback: 'Produce',
      ),
      category: stringFrom(<String>['category']),
      parish: stringFrom(
        <String>['parish', 'demand_parish', 'region'],
        fallback: 'Jamaica',
      ),
      unit: stringFrom(<String>['unit'], fallback: 'lb'),
      harvestCircleId: circleValue.isEmpty ? null : circleValue,
      socialMentions: integer(
        valueFrom(<String>[
          'social_mentions',
          'meal_mentions',
          'meal_pulse_mentions',
        ]),
      ),
      customerInterestCount: integer(
        valueFrom(<String>[
          'customer_interest_count',
          'follow_count',
          'follower_count',
        ]),
      ),
      harvestCircleHouseholds: integer(
        valueFrom(<String>[
          'reserved_households',
          'harvest_circle_households',
          'household_count',
          'reservation_households',
        ]),
      ),
      recentOrderCount: integer(
        valueFrom(<String>[
          'recent_order_count',
          'retail_order_count',
          'customer_order_count',
        ]),
      ),
      businessNeedCount: integer(
        valueFrom(<String>[
          'business_need_count',
          'business_demand_count',
          'wholesale_need_count',
        ]),
      ),
      socialInterestScore: number(
        valueFrom(<String>[
          'social_interest_score',
          'social_score',
        ]),
      ),
      reservedDemand: number(
        valueFrom(<String>[
          'reserved_demand',
          'reserved_quantity',
          'harvest_circle_reserved',
        ]),
      ),
      retailOrderDemand: number(
        valueFrom(<String>[
          'recent_order_quantity',
          'retail_order_demand',
          'customer_order_demand',
          'retail_demand',
        ]),
      ),
      businessDemand: number(
        valueFrom(<String>[
          'business_demand',
          'wholesale_demand',
          'business_demand_quantity',
        ]),
      ),
      verifiedDemand: verified,
      futureDemandQuantity: futureDemand,
      confirmedSupply: confirmed,
      supplyGap: gap < 0 ? 0.0 : gap,
      opportunityScore: number(
        valueFrom(<String>[
          'opportunity_score',
          'demand_score',
          'score',
        ]),
      ),
      confidence: stringFrom(
        <String>['confidence', 'confidence_level', 'demand_confidence'],
        fallback: verified > 0 ? 'medium' : 'social',
      ).toLowerCase(),
      signalStatus: stringFrom(
        <String>['signal_status', 'status', 'opportunity_status'],
        fallback: gap > 0 ? 'gap' : 'watch',
      ).toLowerCase(),
      overplantGuard: overplant,
      recommendedAction: recommendation,
      needWindowStart: dateFrom(
        <String>['need_window_start', 'window_start', 'need_from'],
      ),
      needWindowEnd: dateFrom(
        <String>['need_window_end', 'window_end', 'need_by'],
      ),
    );
  }

  bool get hasVerifiedGap => verifiedDemand > 0 && supplyGap > 0.0001;

  bool get isCovered =>
      verifiedDemand > 0 && confirmedSupply + 0.0001 >= verifiedDemand;

  // Phase 97 compatibility aliases used by Farmer + Admin intelligence views.
  int get reservedHouseholds => harvestCircleHouseholds;
  double get reservedQuantity => reservedDemand;
  double get recentOrderQuantity => retailOrderDemand;
  double get businessDemandQuantity => businessDemand;
  double get confirmedSupplyQuantity => confirmedSupply;

  bool get isHighConfidence {
    final clean = confidence.trim().toLowerCase();
    return clean == 'high' ||
        clean == 'verified' ||
        clean == 'committed' ||
        clean == 'confirmed';
  }

  bool get isSocialOnly =>
      verifiedDemand <= 0.0001 &&
      (socialMentions > 0 || socialInterestScore > 0);

  String get confidenceLabel {
    switch (confidence.trim().toLowerCase()) {
      case 'high':
      case 'verified':
      case 'confirmed':
      case 'committed':
        return 'High';
      case 'medium':
      case 'moderate':
        return 'Medium';
      case 'low':
        return 'Low';
      case 'social':
      case 'social_only':
        return 'Social';
      default:
        return confidence.trim().isEmpty ? 'Watch' : confidence.trim();
    }
  }

  String get statusLabel {
    switch (signalStatus.trim().toLowerCase()) {
      case 'gap':
      case 'verified_gap':
      case 'opportunity':
        return 'Supply Opportunity';
      case 'covered':
        return 'Covered';
      case 'surplus':
        return 'Supply Ahead';
      case 'social':
      case 'social_only':
        return 'Social Interest';
      default:
        return 'Watch';
    }
  }
}

class HpjParishDemandPulse {
  final String parish;
  final String cropName;
  final String category;
  final String unit;

  final int socialMentions;
  final int customerInterestCount;
  final int householdCount;
  final int businessNeedCount;

  final double reservedDemand;
  final double retailOrderDemand;
  final double businessDemand;
  final double verifiedDemand;
  final double confirmedSupply;
  final double supplyGap;

  final String confidence;
  final String signalStatus;

  const HpjParishDemandPulse({
    required this.parish,
    required this.cropName,
    required this.category,
    required this.unit,
    required this.socialMentions,
    required this.customerInterestCount,
    required this.householdCount,
    required this.businessNeedCount,
    required this.reservedDemand,
    required this.retailOrderDemand,
    required this.businessDemand,
    required this.verifiedDemand,
    required this.confirmedSupply,
    required this.supplyGap,
    required this.confidence,
    required this.signalStatus,
  });

  factory HpjParishDemandPulse.fromSupabase(
    Map<String, dynamic> data,
  ) {
    double number(dynamic value) {
      if (value is num) return value.toDouble();
      return double.tryParse(value?.toString() ?? '') ?? 0;
    }

    int integer(dynamic value) {
      if (value is num) return value.toInt();
      return int.tryParse(value?.toString() ?? '') ?? 0;
    }

    String stringFrom(List<String> keys, {String fallback = ''}) {
      for (final key in keys) {
        final value = data[key];
        if (value == null) continue;
        final clean = value.toString().trim();
        if (clean.isNotEmpty) return clean;
      }
      return fallback;
    }

    dynamic valueFrom(List<String> keys) {
      for (final key in keys) {
        if (data.containsKey(key) && data[key] != null) return data[key];
      }
      return null;
    }

    final verified = number(
      valueFrom(<String>[
        'future_demand_quantity',
        'verified_demand',
        'committed_demand',
        'confirmed_demand',
      ]),
    );

    final confirmed = number(
      valueFrom(<String>[
        'confirmed_supply_quantity',
        'confirmed_supply',
        'hpj_confirmed_supply',
        'verified_supply',
      ]),
    );

    final rawGap = valueFrom(<String>[
      'supply_gap',
      'verified_gap',
      'opportunity_gap',
    ]);

    final double gap = rawGap == null
        ? (verified - confirmed > 0 ? verified - confirmed : 0.0)
        : number(rawGap);

    return HpjParishDemandPulse(
      parish: stringFrom(
        <String>['parish', 'demand_parish', 'region'],
        fallback: 'Jamaica',
      ),
      cropName: stringFrom(
        <String>['crop_name', 'product_name', 'ingredient_name'],
        fallback: 'Produce',
      ),
      category: stringFrom(<String>['category']),
      unit: stringFrom(<String>['unit'], fallback: 'lb'),
      socialMentions: integer(
        valueFrom(<String>[
          'social_mentions',
          'meal_mentions',
          'meal_pulse_mentions',
        ]),
      ),
      customerInterestCount: integer(
        valueFrom(<String>[
          'customer_interest_count',
          'follower_count',
          'follow_count',
        ]),
      ),
      householdCount: integer(
        valueFrom(<String>[
          'household_count',
          'reservation_households',
          'harvest_circle_households',
        ]),
      ),
      businessNeedCount: integer(
        valueFrom(<String>[
          'business_need_count',
          'business_demand_count',
          'wholesale_need_count',
        ]),
      ),
      reservedDemand: number(
        valueFrom(<String>[
          'reserved_demand',
          'reserved_quantity',
          'harvest_circle_reserved',
        ]),
      ),
      retailOrderDemand: number(
        valueFrom(<String>[
          'retail_order_demand',
          'customer_order_demand',
          'retail_demand',
        ]),
      ),
      businessDemand: number(
        valueFrom(<String>[
          'business_demand',
          'wholesale_demand',
          'business_demand_quantity',
        ]),
      ),
      verifiedDemand: verified,
      confirmedSupply: confirmed,
      supplyGap: gap < 0 ? 0.0 : gap,
      confidence: stringFrom(
        <String>['confidence', 'confidence_level', 'demand_confidence'],
        fallback: verified > 0 ? 'medium' : 'social',
      ).toLowerCase(),
      signalStatus: stringFrom(
        <String>['signal_status', 'status', 'opportunity_status'],
        fallback: gap > 0 ? 'gap' : 'watch',
      ).toLowerCase(),
    );
  }

  bool get hasVerifiedGap => verifiedDemand > 0 && supplyGap > 0.0001;

  bool get isCovered =>
      verifiedDemand > 0 && confirmedSupply + 0.0001 >= verifiedDemand;

  // Compatibility aliases for the Phase 97 Admin parish table.
  double get businessDemandQuantity => businessDemand;
  double get confirmedSupplyQuantity => confirmedSupply;
}

Future<List<HpjGrowIntelligenceSignal>> fetchHpjGrowIntelligence({
  int historyDays = 30,
  int futureDays = 60,
  int limit = 40,
}) async {
  const rpcCandidates = <String>[
    'hpj_get_grow_intelligence',
    'hpj_grow_intelligence',
  ];

  Object? lastError;
  final safeHistoryDays = historyDays < 1 ? 1 : historyDays;
  final safeFutureDays = futureDays < 1 ? 1 : futureDays;
  final safeLimit = limit < 1 ? 1 : (limit > 500 ? 500 : limit);

  for (final rpcName in rpcCandidates) {
    try {
      dynamic response;
      try {
        response = await supabase.rpc(
          rpcName,
          params: <String, dynamic>{
            'p_days': safeHistoryDays,
            'p_future_days': safeFutureDays,
            'p_limit': safeLimit,
          },
        );
      } catch (parameterizedError) {
        // Compatibility with an older/no-argument RPC alias.
        response = await supabase.rpc(rpcName);
      }
      final rows = response is List ? response : const <dynamic>[];

      return rows
          .whereType<Map>()
          .map(
            (item) => HpjGrowIntelligenceSignal.fromSupabase(
              Map<String, dynamic>.from(item),
            ),
          )
          .toList(growable: false);
    } catch (error) {
      lastError = error;
    }
  }

  // Compatibility fallback if the Phase 97 migration exposed a view instead
  // of one of the RPC aliases above.
  const viewCandidates = <String>[
    'hpj_grow_intelligence',
    'hpj_grow_intelligence_view',
  ];

  for (final viewName in viewCandidates) {
    try {
      final response = await supabase.from(viewName).select().limit(safeLimit);
      return (response as List)
          .whereType<Map>()
          .map(
            (item) => HpjGrowIntelligenceSignal.fromSupabase(
              Map<String, dynamic>.from(item),
            ),
          )
          .toList(growable: false);
    } catch (error) {
      lastError = error;
    }
  }

  farmDebugLog(
    'Phase 97 grow intelligence unavailable safely: $lastError',
  );
  return const <HpjGrowIntelligenceSignal>[];
}

Future<List<HpjParishDemandPulse>> fetchHpjParishDemandPulse({
  int historyDays = 30,
  int futureDays = 60,
  int limit = 100,
}) async {
  const rpcCandidates = <String>[
    'hpj_get_parish_demand_pulse',
    'hpj_parish_demand_pulse',
  ];

  Object? lastError;
  final safeHistoryDays = historyDays < 1 ? 1 : historyDays;
  final safeFutureDays = futureDays < 1 ? 1 : futureDays;
  final safeLimit = limit < 1 ? 1 : (limit > 500 ? 500 : limit);

  for (final rpcName in rpcCandidates) {
    try {
      dynamic response;
      try {
        response = await supabase.rpc(
          rpcName,
          params: <String, dynamic>{
            'p_days': safeHistoryDays,
            'p_future_days': safeFutureDays,
            'p_limit': safeLimit,
          },
        );
      } catch (parameterizedError) {
        response = await supabase.rpc(rpcName);
      }
      final rows = response is List ? response : const <dynamic>[];

      return rows
          .whereType<Map>()
          .map(
            (item) => HpjParishDemandPulse.fromSupabase(
              Map<String, dynamic>.from(item),
            ),
          )
          .toList(growable: false);
    } catch (error) {
      lastError = error;
    }
  }

  const viewCandidates = <String>[
    'hpj_parish_demand_pulse',
    'hpj_parish_demand_pulse_view',
  ];

  for (final viewName in viewCandidates) {
    try {
      final response = await supabase.from(viewName).select().limit(safeLimit);
      return (response as List)
          .whereType<Map>()
          .map(
            (item) => HpjParishDemandPulse.fromSupabase(
              Map<String, dynamic>.from(item),
            ),
          )
          .toList(growable: false);
    } catch (error) {
      lastError = error;
    }
  }

  farmDebugLog(
    'Phase 97 parish demand pulse unavailable safely: $lastError',
  );
  return const <HpjParishDemandPulse>[];
}


// ============================================================================
// HPJ PHASE 116 — CREATOR PROFILES + MEAL COLLECTIONS
// ============================================================================

class HpjMealCreatorProfile {
  final String userId;
  final String username;
  final String displayName;
  final String bio;
  final String avatarUrl;
  final int followerCount;
  final int followingCount;
  final int mealCount;
  final bool isFollowing;
  final bool isMe;

  const HpjMealCreatorProfile({
    required this.userId,
    required this.username,
    required this.displayName,
    required this.bio,
    required this.avatarUrl,
    required this.followerCount,
    required this.followingCount,
    required this.mealCount,
    required this.isFollowing,
    required this.isMe,
  });

  factory HpjMealCreatorProfile.fromSupabase(Map<String, dynamic> row) {
    int integer(dynamic value) {
      if (value is num) return value.toInt();
      return int.tryParse(value?.toString() ?? '') ?? 0;
    }

    bool truthy(dynamic value) {
      if (value is bool) return value;
      final clean = value?.toString().trim().toLowerCase() ?? '';
      return clean == 'true' || clean == '1' || clean == 't';
    }

    return HpjMealCreatorProfile(
      userId: (row['user_id'] ?? '').toString().trim(),
      username: (row['username'] ?? '').toString().trim(),
      displayName: (row['display_name'] ?? 'HPJ Member').toString().trim(),
      bio: (row['bio'] ?? '').toString().trim(),
      avatarUrl: (row['avatar_url'] ?? '').toString().trim(),
      followerCount: integer(row['follower_count']),
      followingCount: integer(row['following_count']),
      mealCount: integer(row['meal_count']),
      isFollowing: truthy(row['is_following']),
      isMe: truthy(row['is_me']),
    );
  }
}

class HpjMealCollectionSummary {
  final String id;
  final String name;
  final String description;
  final int itemCount;
  final String coverImageUrl;
  final bool isPublic;
  final bool isOwner;

  const HpjMealCollectionSummary({
    required this.id,
    required this.name,
    required this.description,
    required this.itemCount,
    required this.coverImageUrl,
    required this.isPublic,
    required this.isOwner,
  });

  factory HpjMealCollectionSummary.fromSupabase(Map<String, dynamic> row) {
    int integer(dynamic value) {
      if (value is num) return value.toInt();
      return int.tryParse(value?.toString() ?? '') ?? 0;
    }

    bool truthy(dynamic value) {
      if (value is bool) return value;
      final clean = value?.toString().trim().toLowerCase() ?? '';
      return clean == 'true' || clean == '1' || clean == 't';
    }

    return HpjMealCollectionSummary(
      id: (row['id'] ?? '').toString().trim(),
      name: (row['name'] ?? 'Meal collection').toString().trim(),
      description: (row['description'] ?? '').toString().trim(),
      itemCount: integer(row['item_count']),
      coverImageUrl: (row['cover_image_url'] ?? '').toString().trim(),
      isPublic: truthy(row['is_public']),
      isOwner: truthy(row['is_owner']),
    );
  }
}

Future<HpjMealCreatorProfile?> fetchHpjMealCreatorProfile(
  String creatorUserId,
) async {
  final clean = creatorUserId.trim();
  if (clean.isEmpty) return null;

  try {
    final response = await supabase.rpc(
      'hpj_get_meal_creator_profile',
      params: <String, dynamic>{'p_creator_user_id': clean},
    );

    if (response is! List || response.isEmpty) return null;
    return HpjMealCreatorProfile.fromSupabase(
      Map<String, dynamic>.from(response.first as Map),
    );
  } catch (error) {
    farmDebugLog('Creator profile unavailable: $error');
    return null;
  }
}

Future<List<HpjMealPost>> fetchHpjMealCreatorPosts(
  String creatorUserId, {
  int limit = 24,
}) async {
  try {
    final response = await supabase.rpc(
      'hpj_get_meal_creator_posts',
      params: <String, dynamic>{
        'p_creator_user_id': creatorUserId.trim(),
        'p_limit': limit,
      },
    );

    return (response as List)
        .map(
          (row) => HpjMealPost.fromSupabase(
            Map<String, dynamic>.from(row as Map),
          ),
        )
        .toList(growable: false);
  } catch (error) {
    farmDebugLog('Creator meals unavailable: $error');
    return const <HpjMealPost>[];
  }
}

Future<List<HpjMealCollectionSummary>> fetchHpjMealCollections(
  String creatorUserId,
) async {
  try {
    final response = await supabase.rpc(
      'hpj_get_meal_collections',
      params: <String, dynamic>{
        'p_creator_user_id': creatorUserId.trim(),
      },
    );

    return (response as List)
        .map(
          (row) => HpjMealCollectionSummary.fromSupabase(
            Map<String, dynamic>.from(row as Map),
          ),
        )
        .toList(growable: false);
  } catch (error) {
    farmDebugLog('Meal collections unavailable: $error');
    return const <HpjMealCollectionSummary>[];
  }
}

Future<String> createHpjMealCollection({
  required String name,
  String description = '',
  bool isPublic = true,
}) async {
  final response = await supabase.rpc(
    'hpj_create_meal_collection',
    params: <String, dynamic>{
      'p_name': name.trim(),
      'p_description': description.trim(),
      'p_is_public': isPublic,
    },
  );
  return response?.toString() ?? '';
}

Future<void> addHpjMealToCollection({
  required String collectionId,
  required String postId,
}) async {
  await supabase.rpc(
    'hpj_add_meal_to_collection',
    params: <String, dynamic>{
      'p_collection_id': collectionId.trim(),
      'p_post_id': postId.trim(),
    },
  );
}

Future<void> editHpjMealCreatorProfile({
  required String username,
  required String bio,
}) async {
  await supabase.rpc(
    'hpj_upsert_meal_creator_profile',
    params: <String, dynamic>{
      'p_username': username.trim().toLowerCase(),
      'p_bio': bio.trim(),
      'p_avatar_url': null,
      'p_is_public': true,
    },
  );
}

Future<void> showHpjMealCollectionPicker(
  BuildContext context,
  HpjMealPost post,
) async {
  final user = supabase.auth.currentUser;
  if (user == null) return;

  var collections = await fetchHpjMealCollections(user.id);
  if (!context.mounted) return;

  await showModalBottomSheet<void>(
    context: context,
    useSafeArea: true,
    isScrollControlled: true,
    showDragHandle: true,
    builder: (sheetContext) {
      return StatefulBuilder(
        builder: (context, setLocalState) {
          Future<void> createCollection() async {
            final controller = TextEditingController();
            final name = await showDialog<String>(
              context: context,
              builder: (dialogContext) => AlertDialog(
                title: const Text('New meal collection'),
                content: TextField(
                  controller: controller,
                  autofocus: true,
                  maxLength: 60,
                  decoration: const InputDecoration(
                    labelText: 'Collection name',
                    hintText: 'Sunday dinners',
                  ),
                ),
                actions: [
                  TextButton(
                    onPressed: () => Navigator.pop(dialogContext),
                    child: const Text('Cancel'),
                  ),
                  FilledButton(
                    onPressed: () => Navigator.pop(
                      dialogContext,
                      controller.text.trim(),
                    ),
                    child: const Text('Create'),
                  ),
                ],
              ),
            );
            controller.dispose();

            if (name == null || name.trim().isEmpty) return;

            try {
              await createHpjMealCollection(name: name);
              collections = await fetchHpjMealCollections(user.id);
              if (context.mounted) setLocalState(() {});
            } catch (error) {
              if (!context.mounted) return;
              ScaffoldMessenger.of(context).showSnackBar(
                SnackBar(content: Text(friendlyAppError(error))),
              );
            }
          }

          Future<void> add(HpjMealCollectionSummary collection) async {
            try {
              await addHpjMealToCollection(
                collectionId: collection.id,
                postId: post.id,
              );
              if (!context.mounted) return;
              Navigator.of(sheetContext).pop();
              ScaffoldMessenger.of(context).showSnackBar(
                SnackBar(
                  content: Text('Saved to ${collection.name}.'),
                ),
              );
            } catch (error) {
              if (!context.mounted) return;
              ScaffoldMessenger.of(context).showSnackBar(
                SnackBar(content: Text(friendlyAppError(error))),
              );
            }
          }

          return ConstrainedBox(
            constraints: BoxConstraints(
              maxHeight: MediaQuery.sizeOf(context).height * .78,
            ),
            child: ListView(
              padding: const EdgeInsets.fromLTRB(18, 4, 18, 28),
              children: [
                Row(
                  children: [
                    const Expanded(
                      child: Text(
                        'Save to collection',
                        style: TextStyle(
                          color: FarmColors.deepGreen,
                          fontSize: 19,
                          fontWeight: FontWeight.w900,
                        ),
                      ),
                    ),
                    TextButton.icon(
                      onPressed: createCollection,
                      icon: const Icon(Icons.add_rounded),
                      label: const Text('New'),
                    ),
                  ],
                ),
                const SizedBox(height: 8),
                if (collections.isEmpty)
                  const FarmEmptyState(
                    icon: Icons.collections_bookmark_outlined,
                    title: 'No collections yet',
                    message:
                        'Create a collection for meals you want to cook, save or shop later.',
                  )
                else
                  for (final collection in collections)
                    ListTile(
                      leading: const CircleAvatar(
                        backgroundColor: FarmColors.primarySoft,
                        child: Icon(
                          Icons.collections_bookmark_outlined,
                          color: FarmColors.deepGreen,
                        ),
                      ),
                      title: Text(
                        collection.name,
                        style: const TextStyle(
                          fontWeight: FontWeight.w900,
                        ),
                      ),
                      subtitle: Text(
                        '${collection.itemCount} meal${collection.itemCount == 1 ? '' : 's'}',
                      ),
                      trailing: const Icon(Icons.add_rounded),
                      onTap: () => add(collection),
                    ),
              ],
            ),
          );
        },
      );
    },
  );
}

class HpjMealCreatorProfileScreen extends StatefulWidget {
  final String creatorUserId;
  final String fallbackDisplayName;

  const HpjMealCreatorProfileScreen({
    super.key,
    required this.creatorUserId,
    this.fallbackDisplayName = 'HPJ Member',
  });

  @override
  State<HpjMealCreatorProfileScreen> createState() =>
      _HpjMealCreatorProfileScreenState();
}

class _HpjMealCreatorProfileScreenState
    extends State<HpjMealCreatorProfileScreen> {
  late Future<HpjMealCreatorProfile?> _profileFuture;
  late Future<List<HpjMealPost>> _mealsFuture;
  late Future<List<HpjMealCollectionSummary>> _collectionsFuture;

  @override
  void initState() {
    super.initState();
    _reload();
  }

  void _reload() {
    _profileFuture = fetchHpjMealCreatorProfile(widget.creatorUserId);
    _mealsFuture = fetchHpjMealCreatorPosts(widget.creatorUserId);
    _collectionsFuture = fetchHpjMealCollections(widget.creatorUserId);
  }

  Future<void> _refresh() async {
    setState(_reload);
    await Future.wait<dynamic>([
      _profileFuture,
      _mealsFuture,
      _collectionsFuture,
    ]);
  }

  Future<void> _toggleFollow(HpjMealCreatorProfile profile) async {
    if (!isLoggedIn) {
      await Navigator.of(context).push<bool>(
        MaterialPageRoute<bool>(
          builder: (_) => const LoginScreen(returnToPrevious: true),
        ),
      );
      if (!mounted || !isLoggedIn) return;
    }

    await toggleHpjMealCreatorFollow(profile.userId);
    if (!mounted) return;
    await _refresh();
  }

  Future<void> _editProfile(HpjMealCreatorProfile profile) async {
    final username = TextEditingController(text: profile.username);
    final bio = TextEditingController(text: profile.bio);

    final save = await showDialog<bool>(
      context: context,
      builder: (dialogContext) => AlertDialog(
        title: const Text('Edit Meal Pulse profile'),
        content: SizedBox(
          width: 420,
          child: Column(
            mainAxisSize: MainAxisSize.min,
            children: [
              TextField(
                controller: username,
                maxLength: 24,
                decoration: const InputDecoration(
                  labelText: 'Username',
                  prefixText: '@',
                  helperText: 'Letters, numbers, _ and . only',
                ),
              ),
              const SizedBox(height: 8),
              TextField(
                controller: bio,
                maxLength: 220,
                maxLines: 3,
                decoration: const InputDecoration(
                  labelText: 'Bio',
                  hintText: 'Tell Jamaica what you love to cook.',
                ),
              ),
            ],
          ),
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(dialogContext, false),
            child: const Text('Cancel'),
          ),
          FilledButton(
            onPressed: () => Navigator.pop(dialogContext, true),
            child: const Text('Save'),
          ),
        ],
      ),
    );

    if (save == true) {
      try {
        await editHpjMealCreatorProfile(
          username: username.text,
          bio: bio.text,
        );
        if (mounted) await _refresh();
      } catch (error) {
        if (!mounted) return;
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(content: Text(friendlyAppError(error))),
        );
      }
    }

    username.dispose();
    bio.dispose();
  }

  Future<void> _newCollection() async {
    final controller = TextEditingController();
    final name = await showDialog<String>(
      context: context,
      builder: (dialogContext) => AlertDialog(
        title: const Text('New collection'),
        content: TextField(
          controller: controller,
          autofocus: true,
          maxLength: 60,
          decoration: const InputDecoration(
            labelText: 'Collection name',
            hintText: 'Weekend cooking',
          ),
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(dialogContext),
            child: const Text('Cancel'),
          ),
          FilledButton(
            onPressed: () =>
                Navigator.pop(dialogContext, controller.text.trim()),
            child: const Text('Create'),
          ),
        ],
      ),
    );
    controller.dispose();

    if (name == null || name.isEmpty) return;
    try {
      await createHpjMealCollection(name: name);
      if (mounted) await _refresh();
    } catch (error) {
      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(content: Text(friendlyAppError(error))),
      );
    }
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      backgroundColor: const Color(0xFFF7F8F3),
      appBar: AppBar(title: const Text('Meal Pulse Creator')),
      body: RefreshIndicator(
        onRefresh: _refresh,
        child: FutureBuilder<HpjMealCreatorProfile?>(
          future: _profileFuture,
          builder: (context, profileSnapshot) {
            final profile = profileSnapshot.data;

            if (profileSnapshot.connectionState == ConnectionState.waiting &&
                profile == null) {
              return ListView(
                children: [
                  SizedBox(height: 260),
                  Center(child: CircularProgressIndicator()),
                ],
              );
            }

            if (profile == null) {
              return ListView(
                padding: const EdgeInsets.all(18),
                children: [
                  FarmEmptyState(
                    icon: Icons.person_outline_rounded,
                    title: widget.fallbackDisplayName,
                    message: 'This Meal Pulse profile is not available yet.',
                  ),
                ],
              );
            }

            final initial = profile.displayName.trim().isEmpty
                ? 'H'
                : profile.displayName.trim()[0].toUpperCase();

            return ListView(
              physics: const AlwaysScrollableScrollPhysics(),
              padding: const EdgeInsets.fromLTRB(16, 16, 16, 110),
              children: [
                Container(
                  padding: const EdgeInsets.all(18),
                  decoration: BoxDecoration(
                    color: FarmColors.deepGreen,
                    borderRadius: BorderRadius.circular(24),
                  ),
                  child: Row(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      CircleAvatar(
                        radius: 34,
                        backgroundColor: Colors.white.withOpacity(.12),
                        child: Text(
                          initial,
                          style: const TextStyle(
                            color: Colors.white,
                            fontSize: 24,
                            fontWeight: FontWeight.w900,
                          ),
                        ),
                      ),
                      const SizedBox(width: 14),
                      Expanded(
                        child: Column(
                          crossAxisAlignment: CrossAxisAlignment.start,
                          children: [
                            Text(
                              profile.displayName,
                              style: const TextStyle(
                                color: Colors.white,
                                fontSize: 19,
                                fontWeight: FontWeight.w900,
                              ),
                            ),
                            const SizedBox(height: 2),
                            Text(
                              '@${profile.username}',
                              style: TextStyle(
                                color: Colors.white.withOpacity(.72),
                                fontSize: 10.5,
                                fontWeight: FontWeight.w800,
                              ),
                            ),
                            if (profile.bio.isNotEmpty) ...[
                              const SizedBox(height: 8),
                              Text(
                                profile.bio,
                                style: TextStyle(
                                  color: Colors.white.withOpacity(.88),
                                  fontSize: 10.2,
                                  height: 1.4,
                                  fontWeight: FontWeight.w600,
                                ),
                              ),
                            ],
                            const SizedBox(height: 11),
                            Wrap(
                              spacing: 12,
                              runSpacing: 6,
                              children: [
                                Text(
                                  '${profile.mealCount} meals',
                                  style: const TextStyle(
                                    color: Colors.white,
                                    fontWeight: FontWeight.w900,
                                    fontSize: 9.5,
                                  ),
                                ),
                                Text(
                                  '${profile.followerCount} followers',
                                  style: const TextStyle(
                                    color: Colors.white,
                                    fontWeight: FontWeight.w900,
                                    fontSize: 9.5,
                                  ),
                                ),
                                Text(
                                  '${profile.followingCount} following',
                                  style: const TextStyle(
                                    color: Colors.white,
                                    fontWeight: FontWeight.w900,
                                    fontSize: 9.5,
                                  ),
                                ),
                              ],
                            ),
                          ],
                        ),
                      ),
                      const SizedBox(width: 8),
                      if (profile.isMe)
                        OutlinedButton(
                          onPressed: () => _editProfile(profile),
                          style: OutlinedButton.styleFrom(
                            foregroundColor: Colors.white,
                            side: BorderSide(
                              color: Colors.white.withOpacity(.45),
                            ),
                          ),
                          child: const Text('Edit'),
                        )
                      else
                        FilledButton(
                          onPressed: () => _toggleFollow(profile),
                          style: FilledButton.styleFrom(
                            backgroundColor: const Color(0xFFFFD15A),
                            foregroundColor: FarmColors.deepGreen,
                          ),
                          child: Text(
                            profile.isFollowing ? 'Following' : 'Follow',
                          ),
                        ),
                    ],
                  ),
                ),
                const SizedBox(height: 18),
                Row(
                  children: [
                    const Expanded(
                      child: Text(
                        'Meal Collections',
                        style: TextStyle(
                          color: FarmColors.ink,
                          fontSize: 16,
                          fontWeight: FontWeight.w900,
                        ),
                      ),
                    ),
                    if (profile.isMe)
                      TextButton.icon(
                        onPressed: _newCollection,
                        icon: const Icon(Icons.add_rounded),
                        label: const Text('New'),
                      ),
                  ],
                ),
                const SizedBox(height: 8),
                FutureBuilder<List<HpjMealCollectionSummary>>(
                  future: _collectionsFuture,
                  builder: (context, snapshot) {
                    final collections =
                        snapshot.data ?? const <HpjMealCollectionSummary>[];
                    if (collections.isEmpty) {
                      return const Text(
                        'No public meal collections yet.',
                        style: TextStyle(
                          color: FarmColors.mutedText,
                          fontSize: 9.5,
                          fontWeight: FontWeight.w700,
                        ),
                      );
                    }

                    return SizedBox(
                      height: 116,
                      child: ListView.separated(
                        scrollDirection: Axis.horizontal,
                        itemCount: collections.length,
                        separatorBuilder: (_, __) =>
                            const SizedBox(width: 9),
                        itemBuilder: (context, index) {
                          final collection = collections[index];
                          return Material(
                            color: Colors.transparent,
                            child: InkWell(
                              borderRadius: BorderRadius.circular(16),
                              onTap: () {
                                Navigator.of(context).push<void>(
                                  MaterialPageRoute<void>(
                                    builder: (_) => HpjMealCollectionScreen(
                                      collection: collection,
                                    ),
                                  ),
                                );
                              },
                              child: Container(
                                width: 180,
                                padding: const EdgeInsets.all(12),
                                decoration: BoxDecoration(
                                  color: Colors.white,
                                  borderRadius: BorderRadius.circular(16),
                                  border: Border.all(color: FarmColors.line),
                                ),
                                child: Column(
                                  crossAxisAlignment: CrossAxisAlignment.start,
                                  children: [
                                    const Icon(
                                      Icons.collections_bookmark_outlined,
                                      color: FarmColors.primary,
                                    ),
                                    const Spacer(),
                                    Text(
                                      collection.name,
                                      maxLines: 1,
                                      overflow: TextOverflow.ellipsis,
                                      style: const TextStyle(
                                        color: FarmColors.ink,
                                        fontSize: 10.5,
                                        fontWeight: FontWeight.w900,
                                      ),
                                    ),
                                    Text(
                                      '${collection.itemCount} saved meal${collection.itemCount == 1 ? '' : 's'}',
                                      style: const TextStyle(
                                        color: FarmColors.mutedText,
                                        fontSize: 8.3,
                                        fontWeight: FontWeight.w700,
                                      ),
                                    ),
                                  ],
                                ),
                              ),
                            ),
                          );
                        },
                      ),
                    );
                  },
                ),
                const SizedBox(height: 20),
                const Text(
                  'Meals',
                  style: TextStyle(
                    color: FarmColors.ink,
                    fontSize: 16,
                    fontWeight: FontWeight.w900,
                  ),
                ),
                const SizedBox(height: 9),
                FutureBuilder<List<HpjMealPost>>(
                  future: _mealsFuture,
                  builder: (context, snapshot) {
                    final meals = snapshot.data ?? const <HpjMealPost>[];
                    if (meals.isEmpty) {
                      return const FarmEmptyState(
                        icon: Icons.restaurant_outlined,
                        title: 'No meals yet',
                        message:
                            'Meal Pulse posts from this creator will appear here.',
                      );
                    }

                    return LayoutBuilder(
                      builder: (context, constraints) {
                        final columns = constraints.maxWidth >= 900 ? 3 : 2;
                        const gap = 10.0;
                        final width =
                            (constraints.maxWidth - gap * (columns - 1)) /
                                columns;

                        return Wrap(
                          spacing: gap,
                          runSpacing: gap,
                          children: meals.map((meal) {
                            return SizedBox(
                              width: width,
                              child: Container(
                                decoration: BoxDecoration(
                                  color: Colors.white,
                                  borderRadius: BorderRadius.circular(15),
                                  border: Border.all(color: FarmColors.line),
                                ),
                                clipBehavior: Clip.antiAlias,
                                child: Column(
                                  crossAxisAlignment: CrossAxisAlignment.start,
                                  children: [
                                    AspectRatio(
                                      aspectRatio: 4 / 3,
                                      child: meal.imageUrl.isNotEmpty
                                          ? Image.network(
                                              meal.imageUrl,
                                              fit: BoxFit.cover,
                                              errorBuilder: (_, __, ___) =>
                                                  Container(
                                                color: FarmColors.primarySoft,
                                                child: const Icon(
                                                  Icons.restaurant_rounded,
                                                ),
                                              ),
                                            )
                                          : Container(
                                              color: FarmColors.primarySoft,
                                              child: Icon(
                                                meal.videoUrl.isNotEmpty
                                                    ? Icons
                                                        .play_circle_outline_rounded
                                                    : Icons
                                                        .restaurant_rounded,
                                                color: FarmColors.primary,
                                              ),
                                            ),
                                    ),
                                    Padding(
                                      padding: const EdgeInsets.all(9),
                                      child: Text(
                                        meal.mealName,
                                        maxLines: 1,
                                        overflow: TextOverflow.ellipsis,
                                        style: const TextStyle(
                                          color: FarmColors.deepGreen,
                                          fontSize: 9.5,
                                          fontWeight: FontWeight.w900,
                                        ),
                                      ),
                                    ),
                                  ],
                                ),
                              ),
                            );
                          }).toList(growable: false),
                        );
                      },
                    );
                  },
                ),
              ],
            );
          },
        ),
      ),
    );
  }
}


Future<List<HpjMealPost>> fetchHpjMealCollectionPosts(
  String collectionId,
) async {
  try {
    final response = await supabase
        .from('hpj_meal_collection_items')
        .select(
          'created_at, '
          'hpj_meal_posts('
          'id,user_id,display_name,meal_name,caption,meal_type,parish,'
          'ingredients,image_url,video_url,allow_shop,created_at'
          ')',
        )
        .eq('collection_id', collectionId.trim())
        .order('created_at', ascending: false);

    final meals = <HpjMealPost>[];
    for (final raw in response as List) {
      final row = Map<String, dynamic>.from(raw as Map);
      final nested = row['hpj_meal_posts'];
      if (nested is! Map) continue;
      meals.add(
        HpjMealPost.fromSupabase(
          Map<String, dynamic>.from(nested),
        ),
      );
    }
    return meals;
  } catch (error) {
    farmDebugLog('Collection meals unavailable: $error');
    return const <HpjMealPost>[];
  }
}

class HpjMealCollectionScreen extends StatelessWidget {
  final HpjMealCollectionSummary collection;

  const HpjMealCollectionScreen({
    super.key,
    required this.collection,
  });

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      backgroundColor: const Color(0xFFF7F8F3),
      appBar: AppBar(title: Text(collection.name)),
      body: FutureBuilder<List<HpjMealPost>>(
        future: fetchHpjMealCollectionPosts(collection.id),
        builder: (context, snapshot) {
          final meals = snapshot.data ?? const <HpjMealPost>[];

          if (snapshot.connectionState == ConnectionState.waiting &&
              snapshot.data == null) {
            return const Center(child: CircularProgressIndicator());
          }

          if (meals.isEmpty) {
            return const Center(
              child: Padding(
                padding: EdgeInsets.all(24),
                child: FarmEmptyState(
                  icon: Icons.collections_bookmark_outlined,
                  title: 'Collection is empty',
                  message: 'Saved Meal Pulse posts will appear here.',
                ),
              ),
            );
          }

          return ListView.separated(
            padding: const EdgeInsets.fromLTRB(16, 16, 16, 100),
            itemCount: meals.length,
            separatorBuilder: (_, __) => const SizedBox(height: 10),
            itemBuilder: (context, index) {
              final meal = meals[index];

              return FarmCard(
                padding: EdgeInsets.zero,
                child: Row(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    SizedBox(
                      width: 120,
                      height: 100,
                      child: meal.imageUrl.isNotEmpty
                          ? Image.network(
                              meal.imageUrl,
                              fit: BoxFit.cover,
                              errorBuilder: (_, __, ___) => Container(
                                color: FarmColors.primarySoft,
                                child: const Icon(
                                  Icons.restaurant_rounded,
                                  color: FarmColors.primary,
                                ),
                              ),
                            )
                          : Container(
                              color: FarmColors.primarySoft,
                              child: Icon(
                                meal.videoUrl.isNotEmpty
                                    ? Icons.play_circle_outline_rounded
                                    : Icons.restaurant_rounded,
                                color: FarmColors.primary,
                              ),
                            ),
                    ),
                    Expanded(
                      child: Padding(
                        padding: const EdgeInsets.all(12),
                        child: Column(
                          crossAxisAlignment: CrossAxisAlignment.start,
                          children: [
                            Text(
                              meal.mealName,
                              style: const TextStyle(
                                color: FarmColors.ink,
                                fontSize: 12,
                                fontWeight: FontWeight.w900,
                              ),
                            ),
                            const SizedBox(height: 3),
                            Text(
                              meal.displayName,
                              style: const TextStyle(
                                color: FarmColors.mutedText,
                                fontSize: 8.8,
                                fontWeight: FontWeight.w700,
                              ),
                            ),
                            if (meal.ingredients.isNotEmpty) ...[
                              const SizedBox(height: 7),
                              Text(
                                meal.ingredients.take(4).join(' • '),
                                maxLines: 2,
                                overflow: TextOverflow.ellipsis,
                                style: const TextStyle(
                                  color: FarmColors.deepGreen,
                                  fontSize: 8.5,
                                  height: 1.3,
                                  fontWeight: FontWeight.w700,
                                ),
                              ),
                            ],
                          ],
                        ),
                      ),
                    ),
                  ],
                ),
              );
            },
          );
        },
      ),
    );
  }
}
